  str_homestory_chat_11923001 = "Leitura?",
  str_homestory_chat_11923002 = "Gosto muito de ler aqui.",
  str_homestory_chat_11923003 = "Aqui está sempre algum canto sossegado onde nenhum clamor pode chegar...",
