  str_homestory_chat_10921006 = "Isso soa muito como uma farsa.",
  str_homestory_chat_10921007 = "Eu preciso pensar sobre isso.",
  str_homestory_chat_10921008 = "Você se lembra do Guia de Cuidados com a Mala Branca?",
