  str_homestory_chat_15021001 = "O que você está procurando?",
  str_homestory_chat_15021002 = "Temos um gato aqui?",
  str_homestory_chat_15021003 = "Acho que sim...",
  str_homestory_chat_15021004 = "Por favor, mostre-me quando tiver tempo.",
  str_homestory_chat_15021005 = "Tenha certeza. Eu não como gatos.",
  str_homestory_chat_15021006 = "Eu sou principalmente vegetariano, lembra?",
  str_homestory_chat_15021007 = "Sim eu lembro...",
  str_homestory_chat_15021008 = "Acho que não...",
  str_homestory_chat_15021009 = "Quando teremos alguns gatos?",
  str_homestory_chat_15021010 = "Quando os gatos chegarem, não haverá tédio...",
  str_homestory_chat_15022001 = "Você quer falar comigo?",
  str_homestory_chat_15022002 = "Você precisa de um pouco de pó de dente de tubarão, mano?",
