  str_homestory_chat_15022005 = "Experimente, e você verá!",
  str_homestory_chat_15022006 = "Eu não tenho comigo. Próxima vez.",
  str_homestory_chat_15023001 = "Seu dente...",
  str_homestory_chat_15023002 = "Hum? Oh, está um pouco solto novamente.",
  str_homestory_chat_15023003 = "Parece que vou precisar de um novo lote. Você aceita isso?",
  str_homestory_chat_15023004 = "O que isso faz?",
  str_homestory_chat_15023005 = "Não.",
  str_homestory_chat_15023006 = "Vamos! É muito útil.",
  str_homestory_chat_15023007 = "Você pode fazer esculturas com eles ou moê-los e usá-los como temperos.",
  str_homestory_chat_15023008 = "Você pode ganhar algum dinheiro vendendo-os para a Umbraton.",
  str_homestory_chat_15023009 = "Então por que você não os guarda para si mesmo?",
  str_homestory_chat_15023010 = "Porque estou lhe pagando por proteção.",
  str_homestory_chat_15031001 = "Peixe estranho...",
  str_homestory_chat_15031002 = "Hum? Você viu alguma coisa, chefe?",
  str_homestory_chat_15031003 = "Alguns dias atrás, eu vi um bando de peixes no riacho que eu nunca tinha visto antes.",
  str_homestory_chat_15031004 = "Seus olhos eram enormes e seus corpos meio redondos.",
  str_homestory_chat_15031005 = "Oh, você deve estar falando sobre a carpa cabeçuda! Na verdade, fui eu que os coloquei lá...",
  str_homestory_chat_15031006 = "Hã?",
  str_homestory_chat_15031007 = "Bem, notei que a carpa cabeçuda se dá muito bem por aqui.",
  str_homestory_chat_15031008 = "A água, o clima, a velocidade da corrente são perfeitos para eles! Mas o mais importante é que eles são muito raros!",
  str_homestory_chat_15031009 = "E aqui eu pensei que você queria comê-los...",
  str_homestory_chat_15031010 = "Vamos chefe! De dentes afiados como sou, nunca como carne!",
  str_homestory_chat_15031011 = "Quantas vezes mais vocês vão me julgar errado pela minha aparência?",
  str_homestory_chat_15031012 = "Eu tenho que lidar com isso para o resto da minha vida?!",
  str_homestory_chat_15031013 = "Aqui vai de novo...",
  str_homestory_chat_15031014 = "Não seja tão tímido! Você estava em uma gangue antes, não estava?",
  str_homestory_chat_15031015 = "Sim, mas você continua fazendo isso de novo e de novo...",
  str_homestory_chat_15031016 = "Uh... Korgon, por que você trouxe essas carpas cabeçudas aqui em primeiro lugar?",
  str_homestory_chat_15031017 = "Para deixá-los procriar, é claro! E assim que houver muitos deles, vou trazê-los todos de volta para a Ilha Sharkfang.",
  str_homestory_chat_15031018 = "A reconstrução tem me desgastado ultimamente. Parece que o trabalho nunca acaba!",
  str_homestory_chat_15031019 = "Mas só de ver esses carinhas fofos faz todo o meu cansaço ir embora! É por isso que quero trazê-los para a ilha.",
  str_homestory_chat_15031020 = "Vê-los nadando em todas as formas e tamanhos—",
  str_homestory_chat_15031021 = "Espere! Eles vêm em tamanhos diferentes?",
  str_homestory_chat_15031022 = "Sim, viu? Parece assim.",
  str_homestory_chat_15031023 = "Mas só vejo um tamanho...",
  str_homestory_chat_15031024 = "De qualquer forma, Bighead Carp são extremamente ariscos. Levei uma eternidade só para encontrar alguns lugares onde eles moram.",
  str_homestory_chat_15031025 = "Também não são fáceis de apanhar...",
  str_homestory_chat_15031026 = "Se você precisar de alguém para pescá-los, eu posso lidar com isso.",
  str_homestory_chat_15031027 = "S-Sério, chefe?! Isso seria uma grande carga dos meus ombros. Obrigada!",
  str_homestory_chat_15031028 = "Mas como eu disse, Bighead Carp são extremamente raros. Estou um pouco relutante em ver qualquer um deles ir, para ser honesto...",
  str_homestory_chat_15031029 = "Certo, certo... Qual é o problema?",
  str_homestory_chat_15031030 = "Rápido como uma raposa, como sempre! Então o negócio é, você me traz uma dessas carpas cabeçudas menores, e eu compartilharei algumas informações valiosas com você.",
  str_homestory_chat_15031031 = "Eu vou te dizer exatamente onde você pode pescar uma carpa cabeçuda ainda maior! Mas o que acontece depois disso depende de suas habilidades de pesca, chefe.",
  str_homestory_chat_15031032 = "Claro, também estou disposto a oferecer algumas outras recompensas por me trazer mais Bighead Carp. Eu sou um cara legal, afinal!",
  str_homestory_chat_15031033 = "Para cada carpa cabeçuda que você me trouxer, eu lhe direi onde encontrar uma maior!",
  str_homestory_chat_15031034 = "Ouvi dizer que alguns são tão pesados quanto 50 quilos! Você pode acreditar nisso?!",
  str_homestory_chat_15031035 = "Além disso, há uma chance de você pescar uma carpa cabeçuda especialmente rara e brilhante!",
  str_homestory_chat_15031036 = "Bem, você definitivamente está vendendo isso para mim como alguém de Umbraton...",
  str_homestory_chat_15031037 = "Mas eu não tenho o menor peixe para lhe dar agora.",
  str_homestory_chat_15031038 = "Está bem, chefe! Conheço muitos lugares onde você pode encontrar esses carinhas, embora você só pegue o menor do grupo nessas áreas.",
  str_homestory_chat_15031039 = "Mas se você tem as habilidades para o trabalho, você só precisa me trazer o pequenino, e ficarei mais do que feliz em trocá-lo!",
  str_homestory_chat_15031040 = "Eles vão do pequeno, ao pequeno, ao médio, ao grande...",
  str_homestory_chat_15031041 = "E se você chegar tão longe, eu vou garantir que você pegue um ainda maior! Você pode até ter a sorte de pegar aquele raro e brilhante também!",
  str_homestory_chat_15031042 = "Entendi.",
  str_homestory_chat_15031043 = "Então você está pronto para isso, chefe? Aposto que você pode lidar com isso!",
  str_homestory_chat_15031044 = "Você tem outras perguntas?",
  str_homestory_chat_15031045 = "Quero pegar uma carpa cabeçuda ainda maior.",
  str_homestory_chat_15031046 = "Não é um problema! Há muitos pontos de pesca por aí. Tudo se resume ao quão grande estamos falando aqui!",
  str_homestory_chat_15031047 = "Eu quero pegar uma carpa cabeçuda pequena.",
  str_homestory_chat_15031048 = "Se você quiser saber onde pegar a carpa cabeçuda pequena, primeiro terá que me trazer uma carpa cabeçuda. Você já conseguiu um?",
  str_homestory_chat_15031049 = "Dê uma carpa cabeçuda ({1}/1)",
  str_homestory_chat_15031050 = "Deixe-me pensar sobre isso.",
  str_homestory_chat_15031051 = "Eu quero pegar uma carpa cabeçuda média.",
  str_homestory_chat_15031052 = "Se você quiser saber onde pegar a carpa cabeçuda média, primeiro você precisa me trazer uma carpa cabeçuda pequena. Você já conseguiu um?",
  str_homestory_chat_15031053 = "Dê carpa cabeçuda pequena ({1}/1)",
  str_homestory_chat_15031054 = "Deixe-me pensar sobre isso.",
  str_homestory_chat_15031055 = "Eu quero pegar uma Carpa Grande Cabeçuda.",
  str_homestory_chat_15031056 = "Se você quer saber onde pegar a carpa cabeçuda grande, primeiro você precisa me trazer uma carpa cabeçuda média. Você já conseguiu um?",
  str_homestory_chat_15031057 = "Dê carpa cabeçuda média ({1}/1)",
  str_homestory_chat_15031058 = "Deixe-me pensar sobre isso.",
  str_homestory_chat_15031059 = "Eu quero pegar uma carpa cabeçuda gigante.",
  str_homestory_chat_15031060 = "Se você quer saber onde pegar a Carpa Cabeçuda Gigante, primeiro você precisa me trazer uma Carpa Cabeçuda Grande. Você já conseguiu um?",
  str_homestory_chat_15031061 = "Dê carpa cabeçuda ({1}/1)",
  str_homestory_chat_15031062 = "Deixe-me pensar sobre isso.",
  str_homestory_chat_15031063 = "Você é o cara, chefe! Eu não posso te dizer o quão feliz eu estou!",
  str_homestory_chat_15031064 = "Verifique seu mapa. Vou marcar onde você pode encontrar peixes ainda maiores!",
