  str_homestory_chat_26703011 = "Isso não está ajudando...",
  str_homestory_chat_26704001 = "O que está em sua mente?",
  str_homestory_chat_26704002 = "Às vezes me pergunto se precisamos perceber a magia de forma diferente.",
