  str_homestory_chat_26704007 = "Mas e se o mago já resolveu com a pessoa?",
  str_homestory_chat_26704008 = "Entendo, é uma questão de perspectiva.",
  str_homestory_chat_26705001 = "Qual é a sua bebida favorita?",
  str_homestory_chat_26705002 = "Café preto, sem açúcar e sem leite.",
  str_homestory_chat_26705003 = "Mas é amargo.",
  str_homestory_chat_26705004 = "A doçura vem depois da amargura.",
