  str_homestory_chat_27223007 = "Estou procurando recomendações de contos! Especialmente bons thrillers, se você souber de algum...",
  str_homestory_chat_27223008 = "Você parece gostar muito de terror. Você não se assusta?",
  str_homestory_chat_27223009 = "Ah! O que é mais assustador do que estar quebrado?",
  str_homestory_chat_27223010 = "Além disso, e se um dia eles fizerem adaptações cinematográficas para algumas dessas histórias? Eles podem me escalar como protagonista feminina se eu souber o material por dentro e por fora!",
  str_homestory_chat_27223011 = "Então, finalmente posso ser a estrela que estou destinada a ser... Hehehehe...",
