  str_homestory_chat_27321011 = "Isso é muito profissional da sua parte...",
  str_homestory_chat_27322001 = "Como posso ajudar?",
  str_homestory_chat_27322002 = "Bom dia, PlayerName. Por favor, você poderia me fornecer a hora exata agora?",
  str_homestory_chat_27322003 = "Claro...? Há algo errado com o seu relógio?",
  str_homestory_chat_27322004 = "Mesmo o instrumento mais preciso pode falhar às vezes. Na verdade, esta manhã...",
  str_homestory_chat_27322005 = "Percebi que meu relógio parecia estar funcionando uma fração de segundo mais devagar do que ontem.",
  str_homestory_chat_27322006 = "Você percebe coisas assim?!",
  str_homestory_chat_27322007 = "Como um mordomo orgulhoso, é meu dever acompanhar o tempo todo o tempo.",
  str_homestory_chat_27322008 = "Afinal, mesmo o menor desvio da hora exata da minha parte poderia arruinar toda a agenda do meu mestre para o dia.",
  str_homestory_chat_27322009 = "Não posso deixar de sentir ciúmes do seu mestre...",
  str_homestory_chat_27322010 = "Se ao menos eu tivesse alguém como você para me ajudar a me manter dentro do cronograma...",
  str_homestory_chat_27323001 = "Tem algo em mente, Minos?",
  str_homestory_chat_27323002 = "Existe, de fato. Diga-me, como você acha que um mordomo serve melhor ao seu mestre?",
  str_homestory_chat_27323003 = "Seguindo ordens?",
  str_homestory_chat_27323004 = "Obediência total...",
  str_homestory_chat_27323005 = "Se me permite falar francamente... discordo completamente.",
  str_homestory_chat_27323006 = "Ao apoiá-los?",
  str_homestory_chat_27323007 = "Tem razão!",
  str_homestory_chat_27323008 = "O dever de um mordomo não é simplesmente obedecer aos comandos de seu mestre. Na maioria das vezes, ele deve ajudar seu mestre a perceber seus próprios erros.",
  str_homestory_chat_27323009 = "A este respeito, um mordomo e seu mestre podem se ver como iguais.",
  str_homestory_chat_27323010 = "Isso é verdade, sim.",
  str_homestory_chat_27324001 = "Como você se sente sobre este lugar?",
  str_homestory_chat_27324002 = "É um lugar encantador. Vasto, mas incrivelmente limpo.",
  str_homestory_chat_27324003 = "Os Chubbs parecem manter a área muito bem.",
  str_homestory_chat_27324004 = "Não são só eles, sabe? Cada um faz a sua parte para cuidar também do Cloud Gardens.",
  str_homestory_chat_27324005 = "Minha querida PlayerName, você está absolutamente correto.",
  str_homestory_chat_27324006 = "Verdade seja dita, estou com muita inveja de quão habitável é este lugar.",
  str_homestory_chat_27324007 = "O ambiente limpo, o ar puro e até mesmo a quantidade de sol que este lugar recebe... Tudo isso é simplesmente excepcional.",
  str_homestory_chat_27324008 = "Mas o mais importante, é quase totalmente livre de insetos nocivos e outros roedores irritantes. Meu trabalho aqui é muito menos oneroso como resultado.",
  str_homestory_chat_27324009 = "Fico feliz que goste daqui, Minos!",
  str_homestory_chat_26999999 = "Yo yo yo, eu vejo você vagando, mano.",
