  str_homestory_chat_26901002 = "Ei, ei! Eu só estou saindo, sabe?",
  str_homestory_chat_26901003 = "Por que você está copiando o jeito que eu falo?",
  str_homestory_chat_26901004 = "S-Desculpe, ele meio que escapou...",
  str_homestory_chat_26901005 = "Yo yo yo, parece que você pegou no meu fluxo.",
  str_homestory_chat_26921001 = "O que você está lendo?",
