  str_homestory_chat_26921003 = "Vim para Cloud Gardens só para poder ler mais três vezes.",
  str_homestory_chat_26921004 = "Mais três vezes?",
  str_homestory_chat_26921005 = "Sim! Eu poderia lê-lo uma centena de vezes e ainda assim não me cansaria!",
  str_homestory_chat_26921006 = "A julgar pelo quão animado você está, eu diria que você já leu trezentas vezes, não é?",
  str_homestory_chat_26921007 = "Não, mais como 666 vezes!",
  str_homestory_chat_26921008 = "Hã?!",
  str_homestory_chat_26922001 = "Você está sorrindo?",
