  str_homestory_chat_26922006 = "Jardins das Nuvens?",
  str_homestory_chat_26922007 = "Isso mesmo! Eu tenho observado você por um tempo agora, e notei que sempre que você está em Cloud Gardens, você sempre tem um sorriso no rosto.",
