  str_homestory_chat_27825004 = "Bebendo durante o dia...",
  str_homestory_chat_27825005 = "Apenas um pouco de bebida e nada mais. Com uma brisa tão suave, se houvesse outra cadeira de balanço...",
  str_homestory_chat_27825006 = "Maravilha!",
  str_homestory_chat_27825007 = "Então, você não vai mais procurar bestas maravilhosas?",
  str_homestory_chat_27825008 = "Eu vim aqui para relaxar! Mas se não houver bebida...",
