  str_homestory_chat_29122003 = "Sim.",
  str_homestory_chat_29122004 = "Não muito.",
  str_homestory_chat_29122005 = "Por que pergunta?",
  str_homestory_chat_29122006 = "Estou entediado e não tenho quebra-cabeças de palavras para resolver.",
