  str_homestory_chat_29122011 = "Isso porque os quebra-cabeças de palavras são libertadores, especialmente quando você resolve um muito difícil...",
  str_homestory_chat_29122012 = "Você simplesmente não pode descrever como se sente!",
  str_homestory_chat_29122013 = "Eu acho que você deveria se concentrar em relaxar sua mente...",
  str_homestory_chat_29123001 = "O que você está recebendo?",
  str_homestory_chat_29123002 = "Agulha e linhas.",
  str_homestory_chat_29123003 = "Você deve estar costurando alguma coisa. Há um buraco ou rasgo em suas roupas?",
