  str_homestory_chat_29124001 = "Especiarias?",
  str_homestory_chat_29124002 = "Eu quero algumas especiarias para fins de tempero.",
  str_homestory_chat_29124003 = "Parece-me que você está cozinhando algo delicioso.",
  str_homestory_chat_29124004 = "Isso mesmo, estou fazendo um ensopado!",
  str_homestory_chat_29124005 = "Ensopado!",
  str_homestory_chat_29124006 = "Então, que carne você trouxe, especificamente?",
  str_homestory_chat_29124007 = "Carne? Eu não tenho carne.",
  str_homestory_chat_29124008 = "O quê?",
  str_homestory_chat_29124009 = "É muito grande para carregar e vai apodrecer. Alguém vende carne por aqui?",
