  str_homestory_chat_29321001 = "Treinamento de lança?",
  str_homestory_chat_29321002 = "Gostaria de saber se há um instrutor de lança em Cloud Gardens.",
  str_homestory_chat_29321003 = "Aqui é um lugar de paz...",
  str_homestory_chat_29321004 = "É apenas para praticar e ficar em forma, ou a lança pode ficar cega.",
