  str_homestory_chat_29322006 = "Há mais, também.",
  str_homestory_chat_29322007 = "Eles achavam irritante eu acordar muito cedo?",
  str_homestory_chat_29322008 = "Isso também...",
  str_homestory_chat_29322009 = "Então você está dizendo que há mais do que isso?",
