  str_homestory_chat_29322013 = "Mas...",
  str_homestory_chat_29322014 = "De qualquer forma, não seja tão rígido com os outros.",
  str_homestory_chat_29323001 = "O que você gostaria de perguntar a Chubbs?",
  str_homestory_chat_29323002 = "Quero saber se eles podem ser meus escudeiros.",
  str_homestory_chat_29323003 = "Não há precedência para isso em Cloud Gardens, mas você pode fazer isso em Lumopolis?",
