  str_homestory_chat_29324003 = "Um muito bom.",
  str_homestory_chat_29324004 = "Não é um problema, então!",
  str_homestory_chat_29324005 = "Não posso dizer que me importei o suficiente...",
  str_homestory_chat_29324006 = "Suspirar. Vejo que vai ser um problema.",
  str_homestory_chat_29324007 = "O que você está fazendo?",
  str_homestory_chat_29324008 = "Eu gostaria de construir um palco em Cloud Gardens para poder convidar trupes para se apresentar.",
  str_homestory_chat_29324009 = "Se houver espaço, seria bom transformá-lo em uma casa de ópera completa, além de uma ou duas trupes residentes.",
  str_homestory_chat_29324010 = "Então podemos ver a ópera mais recente a qualquer momento.",
  str_homestory_chat_29324011 = "Nossa, acho que isso não é possível...",
  str_homestory_chat_29999999 = "Oi, como você tem passado??",
  str_homestory_chat_29901001 = "Muito bem e você?",
  str_homestory_chat_29901002 = "Eu me adaptei à vida em Cloud Gardens, mas sinto que o ritmo aqui é um pouco lento.",
  str_homestory_chat_29901003 = "Lento?",
  str_homestory_chat_29901004 = "Não seria ótimo se houvesse alguns desafios aqui ocasionalmente, como uma competição de derrubada de árvores?",
  str_homestory_chat_29901005 = "Vamos sentar e relaxar.",
  str_homestory_chat_29921001 = "Bebida?",
  str_homestory_chat_29921002 = "O que você gostaria?",
  str_homestory_chat_29921003 = "Café",
  str_homestory_chat_29921004 = "Uma escolha muito popular. Seria correto dizer que os outros têm influência sobre você?",
  str_homestory_chat_29921005 = "Sim, e muitas vezes acho muito divertido fazer café para você e coisas assim...",
  str_homestory_chat_29921006 = "Se você for a um café, também pode conversar com seus amigos enquanto toma seu café.",
