  str_homestory_chat_29921008 = "Chá",
  str_homestory_chat_29921009 = "O que você gosta no chá? Ouvi dizer que alguns chás são muito amargos.",
  str_homestory_chat_29921010 = "Se você adicionar um pouco de algo a ele, pode ter um ótimo sabor. Além disso, se você adicionar apenas folhas de chá...",
  str_homestory_chat_29921011 = "O primeiro sabor pode ser amargo, mas depois você sentirá uma doçura inexplicável na garganta.",
