  str_homestory_chat_29921013 = "Isso mesmo. Sugiro tentar da próxima vez.",
  str_homestory_chat_29921014 = "Suco",
  str_homestory_chat_29921015 = "Então, você prefere sabores naturais... Bem, isso faz sentido - você é um celestita.",
