  str_homestory_chat_29921018 = "Certo! Isso é ótimo!",
  str_homestory_chat_29921019 = "Água com gás",
  str_homestory_chat_29921020 = "Você realmente gosta de arrotar após cada gole? Inacreditável!",
  str_homestory_chat_29921021 = "Você não acha que está exagerando...?",
  str_homestory_chat_29922001 = "Você quer cultivar algo aqui?",
  str_homestory_chat_29922002 = "Quero começar a trabalhar em um canteiro aqui em Cloud Gardens e cultivar alguns feijões.",
  str_homestory_chat_29922003 = "Claro",
  str_homestory_chat_29922004 = "Ainda deve haver muito espaço aberto aqui... mas primeiro, precisamos perguntar aos Chubbs.",
  str_homestory_chat_29922005 = "Não.",
  str_homestory_chat_29922006 = "Espere, por que feijão?",
  str_homestory_chat_29922007 = "De acordo com a pesquisa da Illumina, esses feijões são as culturas mais adequadas para o cultivo em larga escala e possuem nutrição relativamente alta.",
  str_homestory_chat_29922008 = "E o sabor?",
  str_homestory_chat_29922009 = "Existem inúmeros sabores e inúmeras formas de preparar o feijão!",
  str_homestory_chat_29922010 = "Lembro que havia muitos tipos em Umbraton... Acho que havia um chamado tofu.",
  str_homestory_chat_29922011 = "Eu sei tofu! Ouvi dizer que é do Extremo Oriente — uma comida milagrosa que transforma feijões em mágica!",
  str_homestory_chat_29922012 = "Derrete na boca, e sem tempero, ainda possui um sabor natural de feijão...",
  str_homestory_chat_29922013 = "E é versátil! Seja doce, salgado, azedo ou picante, o tofu pode ser combinado com qualquer tempero!",
  str_homestory_chat_29922014 = "Isso é realmente impressionante...",
  str_homestory_chat_29923001 = "Você quer ir para Umbraton?",
  str_homestory_chat_29923002 = "Depois de ficar em Cloud Gardens por tanto tempo, percebi que não há muita comunicação entre aqui e Umbraton.",
  str_homestory_chat_29923003 = "Sim, Cloud Gardens é um lugar relativamente isolado.",
  str_homestory_chat_29923004 = "Mas esta é uma característica única - esta reclusão permite uma tranquilidade imperturbável.",
  str_homestory_chat_29923005 = "E não é muito difícil chegar a Umbraton daqui...",
  str_homestory_chat_29923006 = "Eu gostaria de poder comprar um pouco de leite de Umbraton regularmente.",
  str_homestory_chat_29923007 = "Leite?",
  str_homestory_chat_29923008 = "A Illumina fornece rações de leite, mas não há nada assim em Cloud Gardens, e também não parece haver uma loja onde eu possa comprar.",
  str_homestory_chat_29923009 = "Certo. Se você quiser beber leite, só pode obtê-lo de fora.",
  str_homestory_chat_29923010 = "Se você realmente quer algumas, lembre-me da próxima vez que eu for a Umbraton e eu pegarei algumas caixas para você.",
  str_homestory_chat_29923011 = "Mas Umbraton não fica exatamente por perto, então receio não poder provar o leite fresco que eles oferecem...",
  str_homestory_chat_29923012 = "Nesse caso... que tal iogurte?",
  str_homestory_chat_29923013 = "Claro, iogurte é bom!",
  str_homestory_chat_29923014 = "Fico feliz em ouvir isso.",
  str_homestory_chat_29924001 = "Uma casa de passarinho?",
  str_homestory_chat_29924002 = "Certo, para pendurar na janela ou no telhado.",
  str_homestory_chat_29924003 = "Quero dizer... por que você quer uma casa de passarinho?",
  str_homestory_chat_29924004 = "Para Aoha. Não posso deixá-lo pousar na ponta dos meus dedos o tempo todo.",
  str_homestory_chat_29924005 = "Principalmente quando estou dormindo... sinto que não tem para onde ir.",
  str_homestory_chat_29924006 = "Soa menos que o ideal.",
  str_homestory_chat_29924007 = "Então, eu gostaria de dar uma casinha. Não precisa ser grande.",
  str_homestory_chat_29924008 = "Eu vi algumas pequenas casas de pássaros em Umbraton. Pareciam bastante simples, mas a madeira...",
  str_homestory_chat_29924009 = "Já pedi aos Chubbs para comprar alguns.",
  str_homestory_chat_29924010 = "Claro que você fez, Yingel. Você é tão eficiente.",
  str_homestory_chat_29924011 = "Você concorda comigo, sim?",
  str_homestory_chat_29924012 = "Não vejo motivo para não... Desde que não ocupe o espaço de mais ninguém.",
  str_homestory_chat_29924013 = "Agora precisamos encontrar um carpinteiro...",
  str_homestory_chat_29924014 = "Parece que ainda temos um caminho a percorrer antes de terminar.",
  str_homestory_chat_29299999 = "É um prazer vê-lo.",
  str_homestory_chat_29201001 = "E aí?",
  str_homestory_chat_29201002 = "Paz, prosperidade - Cloud Gardens é realmente um paraíso. É uma honra poder fazer uma pausa aqui.",
  str_homestory_chat_29201003 = "Aproveite e relaxe o quanto quiser.",
  str_homestory_chat_29201004 = "É por isso que muitas vezes penso comigo mesmo que também devo redobrar meus esforços para proteger este paraíso.",
  str_homestory_chat_29201005 = "E, em particular, não devemos permitir que algum lodo em decomposição polua este lugar, atraindo assim a invasão de entidades malignas.",
  str_homestory_chat_29201006 = "Obrigado por seu trabalho duro.",
  str_homestory_chat_29221001 = "Que fruta você gosta?",
  str_homestory_chat_29221002 = "Por que você me perguntaria isso de repente?",
  str_homestory_chat_29221003 = "Simplesmente surgiu na minha cabeça.",
  str_homestory_chat_29221004 = "Gosto das frutas do sul, principalmente porque são suculentas, nutritivas e possuem uma grande variedade de sabores.",
  str_homestory_chat_29221005 = "E você?",
  str_homestory_chat_29221006 = "Maçãs",
  str_homestory_chat_29221007 = "Esse é um tipo de fruta muito comum. O que você gosta sobre eles?",
  str_homestory_chat_29221008 = "Talvez seja porque eles são tão comuns. Além disso, as maçãs são bastante doces e têm uma textura crocante.",
  str_homestory_chat_29221009 = "Isso mesmo. Por serem tão comuns, há tantas maneiras de prepará-los.",
  str_homestory_chat_29221010 = "Ouvi dizer que eles também podem ser temperados. Com isso em mente, eles podem sim ser considerados uma fruta que realmente beneficia o público.",
  str_homestory_chat_29221011 = "Certo.",
  str_homestory_chat_29221012 = "Uvas",
  str_homestory_chat_29221013 = "As uvas são muito comuns e se tornaram uma fonte popular de muitas bebidas.",
  str_homestory_chat_29221014 = "Como qual?",
  str_homestory_chat_29221015 = "As pessoas bebiam vinho durante as refeições em Lumópolis, e alguns refrigerantes em Illumina também adicionavam suco de uva.",
  str_homestory_chat_29221016 = "Também ouvi dizer que algumas pessoas comem uvas secas como lanches no deserto de Rediesel.",
  str_homestory_chat_29221017 = "Já não estamos a falar de bebidas, pois não?",
  str_homestory_chat_29221018 = "Certo, mas essas passas podem ser usadas como ingrediente em pão doce.",
  str_homestory_chat_29221019 = "Isso é realmente incrível.",
  str_homestory_chat_29222001 = "Que comida você gosta?",
  str_homestory_chat_29222002 = "Eu gosto de comida quente, especialmente carne cozida sem técnicas complicadas.",
  str_homestory_chat_29222003 = "Como assim?",
  str_homestory_chat_29222004 = "Simplificando, gosto de carne cozida, acompanhada com meus temperos favoritos.",
  str_homestory_chat_29222005 = "Parece muito conveniente.",
  str_homestory_chat_29222006 = "Sim - para os soldados, esse tipo de comida é conveniente e delicioso e pode rapidamente repor a força física.",
  str_homestory_chat_29222007 = "Portanto, é importante sempre prestar atenção aos suprimentos de carne para garantir que sempre haja comida quente disponível no campo de batalha.",
  str_homestory_chat_29222008 = "Também pode ser uma questão complicada...",
  str_homestory_chat_29222009 = "Complicado?",
  str_homestory_chat_29222010 = "Há muitas coisas a considerar, sendo a primeira qual combustível usar para cozinhar os alimentos.",
  str_homestory_chat_29222011 = "Em seguida, as considerações vão desde a preservação da carne até a satisfação das preferências gustativas de cada soldado.",
  str_homestory_chat_29222012 = "Essas são todas as coisas que os líderes precisam considerar, e um único erro cometido em qualquer um desses aspectos pode levar à baixa moral.",
  str_homestory_chat_29222013 = "Nossa... não fazia ideia de como você era meticuloso.",
  str_homestory_chat_29223001 = "Desenhar um mapa?",
  str_homestory_chat_29223002 = "Sim. Você é versado na arte da cartografia?",
  str_homestory_chat_29223003 = "Sei um pouco.",
  str_homestory_chat_29223004 = "Excelente. Então eu poderia realmente usar sua ajuda.",
  str_homestory_chat_29223005 = "Não muito.",
  str_homestory_chat_29223006 = "Para que você quer um mapa?",
  str_homestory_chat_29223007 = "Já estou aqui há muitos dias, mas ainda sinto uma certa inquietação no coração.",
  str_homestory_chat_29223008 = "Por que você se sente assim?",
  str_homestory_chat_29223009 = "Depois de muita contemplação, só posso assumir que é devido à minha falta de familiaridade com Cloud Gardens.",
  str_homestory_chat_29223010 = "Deixe-me colocar assim - não estou muito familiarizado com este lugar e sempre me sinto um tanto inseguro quando estou em lugares desconhecidos.",
  str_homestory_chat_29223011 = "Você não precisa se preocupar com estranhos vindo aqui. Você pode relaxar.",
  str_homestory_chat_29223012 = "Seja como for... Ainda sinto que vou precisar dominar o terreno, pesquisando e mapeando para me sentir à vontade.",
  str_homestory_chat_29223013 = "Certo... Continue assim.",
  str_homestory_chat_29224001 = "Olhando para comprar algumas armas?",
  str_homestory_chat_29224002 = "Oh, parece que você me entendeu mal. Eu queria perguntar se você consideraria construir um museu.",
  str_homestory_chat_29224003 = "Um museu?",
  str_homestory_chat_29224004 = "Uma celebrando as armas do mundo, como a longa alabarda de Lumopolis e o sabre de comando de Illumina...",
  str_homestory_chat_29224005 = "Você realmente precisa construir um museu para isso? Parece que não existem tantos tipos de armas disponíveis. Não podemos simplesmente designar uma sala de coleta?",
  str_homestory_chat_29224006 = "Não é isso! Mesmo em algum lugar como a Illumina, com sua tradição de armas produzidas em massa, há uma riqueza de modelos e variedades!",
  str_homestory_chat_29224007 = "Existem dezenas de lanças, revólveres, facas militares e punhais, bem como todas as armas corpo a corpo, armas de longo alcance, armas frias e armas quentes...",
  str_homestory_chat_29224008 = "Além disso, as armas usadas pelos nobres de Lumopolis também vêm em diferentes estilos e trazem insígnias únicas.",
  str_homestory_chat_29224009 = "Eu poderia continuar falando sobre os detalhes para sempre. De qualquer forma, é por isso que uma única sala de coleta não será suficiente.",
  str_homestory_chat_29224010 = "Então, realmente existem tantos tipos... Espere! Você possui todas essas armas?",
  str_homestory_chat_29224011 = "Apenas uma pequena porção, mas isso não me impedirá de começar uma coleção a partir deste momento.",
  str_homestory_chat_29224012 = "Então, você não tem tantos agora... Isso me faz sentir um pouco melhor.",
  str_homestory_chat_29224013 = "Considerando o quão seguro é este lugar, devo ser capaz de manter minha coleção segura aqui. É por isso que quero construir um museu dedicado ao armamento.",
  str_homestory_chat_29224014 = "Deixe-me pensar sobre isso.",
  str_homestory_chat_30099999 = "Alguma notícia hoje?",
  str_homestory_chat_30021001 = "Ei, você tem algum hobby?",
  str_homestory_chat_30021002 = "Hobbies... Por que você pergunta, PlayerName?",
  str_homestory_chat_30021003 = "Eu só quero saber, é tudo.",
  str_homestory_chat_30021004 = "Talvez a observação seja meu único hobby de verdade... E você?",
  str_homestory_chat_30021005 = "Eu realmente não tenho nenhum hobby.",
  str_homestory_chat_30021006 = "Na verdade, não tenho certeza.",
  str_homestory_chat_30021007 = "Talvez seja... andando?",
  str_homestory_chat_30021008 = "Espera, não fui eu que te perguntei?",
  str_homestory_chat_30021009 = "E essa é a minha resposta.",
