  str_homestory_chat_30423004 = "Sim, qual é o problema?",
  str_homestory_chat_30423005 = "Só não pensei que você faria esse tipo de trabalho doméstico.",
  str_homestory_chat_30423006 = "Você se sentiu assim por causa de quem eu era?",
  str_homestory_chat_30423007 = "Hum...",
  str_homestory_chat_30423008 = "Não é nada, fiz principalmente porque gostava de fazer camas para as crianças.",
  str_homestory_chat_30423009 = "Às vezes, quando me levantava de manhã, começava a fazer isso por hábito, embora eles ainda estivessem na cama.",
  str_homestory_chat_30423010 = "Portanto, eles não tinham escolha a não ser acordar cedo e às vezes reclamavam.",
  str_homestory_chat_30423011 = "Eu posso imaginar.",
  str_homestory_chat_30423012 = "Mas isso faz parte de incutir disciplina. Não consigo dormir até tarde, e isso vale para você também!",
  str_homestory_chat_30423013 = "O que? Sim, claro!",
  str_homestory_chat_30424001 = "Música?",
  str_homestory_chat_30424002 = "Isso mesmo. Que tipo de música você gosta?",
  str_homestory_chat_30424003 = "O tipo mais suave.",
  str_homestory_chat_30424004 = "Gosto da música que ouvi em Lumopolis da última vez.",
  str_homestory_chat_30424005 = "Vibração suave e elegante.",
  str_homestory_chat_30424006 = "A audição fácil é certamente uma música muito boa.",
  str_homestory_chat_30424007 = "O tipo mais intenso.",
  str_homestory_chat_30424008 = "Você quer dizer o tipo que soa como barulho...",
  str_homestory_chat_30424009 = "É mais do que isso. Tem ritmos também.",
  str_homestory_chat_30424010 = "Sério?",
  str_homestory_chat_30424011 = "Mas você não acha que é muito tranquilo não ter música aqui?",
  str_homestory_chat_30424012 = "Os sons da natureza servirão. Você pode chamar isso de música também.",
  str_homestory_chat_30424013 = "Mas se é outro tipo de música que você quer, você ainda tem que ir aos locais apropriados.",
  str_homestory_chat_30424014 = "Você tem razão. Eu deveria curtir essa música enquanto estiver em Cloud Gardens.",
  str_homestory_chat_30425001 = "O que eu não gosto?",
  str_homestory_chat_30425002 = "Não consigo pensar em nada de improviso... Por que você quer perguntar isso?",
  str_homestory_chat_30425003 = "O dormitório estava um pouco úmido esta manhã por causa da chuva de alguns dias atrás...",
  str_homestory_chat_30425004 = "Então isso me lembrou dos meus dias em Umbraton.",
  str_homestory_chat_30425005 = "Umbraton... Você pegou a estação das chuvas?",
  str_homestory_chat_30425006 = "Suspiro, estava garoando o dia todo e a cama não era confortável, não importa o que você faça ...",
  str_homestory_chat_30425007 = "Ouvi dizer que é assim em Umbraton, especialmente naqueles meses...",
  str_homestory_chat_30425008 = "Mas não temos muito disso em Cloud Gardens.",
  str_homestory_chat_30425009 = "É por isso que é bom aqui.",
  str_homestory_chat_30599999 = "O que você está fazendo?",
  str_homestory_chat_30521001 = "Ouvi dizer que você está procurando perfumes?",
  str_homestory_chat_30521002 = "Sim. O ar é muito limpo aqui, mas poderia usar um pouco de perfume para acentuá-lo.",
  str_homestory_chat_30521003 = "Por que perfumes?",
  str_homestory_chat_30521004 = "É principalmente para os Chubbs. Eu acho que eles são guias perfeitos.",
  str_homestory_chat_30521005 = "Mas é difícil distinguir muitos deles, a menos que você tenha perfumes.",
  str_homestory_chat_30521006 = "Então, é só para diferenciá-los? Não é um absurdo usar perfumes para isso?",
  str_homestory_chat_30521007 = "Verdade... Com marcadores permanentes, então? Como \"#1\", \"#2\" e assim por diante.",
  str_homestory_chat_30521008 = "Uh... Não importa.",
  str_homestory_chat_30522001 = "Loja de chá?",
  str_homestory_chat_30522002 = "Não temos nada parecido aqui.",
  str_homestory_chat_30522003 = "Ah, não, quero abrir uma casa de chá aqui e estou pesquisando.",
  str_homestory_chat_30522004 = "Pesquisa sobre o quê?",
  str_homestory_chat_30522005 = "O que todo mundo gosta. Por exemplo, o que você gosta de beber?",
  str_homestory_chat_30522006 = "Leite.",
  str_homestory_chat_30522007 = "Hmm, uma escolha saudável.",
  str_homestory_chat_30522008 = "Refrigerantes.",
  str_homestory_chat_30522009 = "Oh? Isso é especial.",
  str_homestory_chat_30522010 = "Café.",
  str_homestory_chat_30522011 = "Legal.",
  str_homestory_chat_30522012 = "Chá preto.",
  str_homestory_chat_30522013 = "Você tem bom gosto!",
  str_homestory_chat_30522014 = "A propósito, você está pesquisando outras pessoas além de mim, certo?",
  str_homestory_chat_30522015 = "Quantos você tem?",
  str_homestory_chat_30522016 = "Ainda estou perguntando uma de cada vez e, em seguida, tenho que classificar as respostas iniciais, intermediárias e tardias, enquanto atualizo de vez em quando.",
  str_homestory_chat_30522017 = "É muita dificuldade para passar...",
