  str_homestory_chat_30523002 = "Sim. Tenho me sentido letárgico ultimamente.",
  str_homestory_chat_30523003 = "Eu pensei sobre isso e percebi que não ia a uma festa dançante há muito tempo.",
  str_homestory_chat_30523004 = "Acho que não há lugar para isso aqui.",
