  str_homestory_chat_30524001 = "Um guia?",
  str_homestory_chat_30524002 = "Sim, sinto que este é um lugar muito grande desde que cheguei aqui.",
  str_homestory_chat_30524003 = "Precisamos ter um guia para que os recém-chegados não se percam.",
  str_homestory_chat_30524004 = "Hum...",
  str_homestory_chat_30524005 = "Então você concorda?",
  str_homestory_chat_30524006 = "Bem, você tem razão.",
  str_homestory_chat_30524007 = "Este é um lugar muito grande e um guia seria muito valioso.",
  str_homestory_chat_30524008 = "Deixe-me pensar sobre isso.",
  str_homestory_chat_30524009 = "Falando nisso, você já tem algum candidato?",
  str_homestory_chat_30524010 = "Os Chubs!",
  str_homestory_chat_30524011 = "O que? Eles?",
  str_homestory_chat_30524012 = "Eles passam o dia inteiro aqui e conhecem o lugar de cabo a rabo. São perfeitos.",
  str_homestory_chat_30524013 = "Uh, vou te dizer uma coisa, deixe-me pensar nisso...",
  str_homestory_chat_30699999 = "Algum projeto interessante?",
  str_homestory_chat_30621001 = "Construindo um parque de diversões?",
  str_homestory_chat_30621002 = "Boa ideia, mas é muito remoto aqui, então como vamos atrair visitantes? Ou talvez focar nos moradores locais?",
  str_homestory_chat_30621003 = "Os Chubs?",
  str_homestory_chat_30621004 = "Exatamente! É uma população pequena, mas quando levamos o futuro em consideração...",
  str_homestory_chat_30621005 = "Como é a taxa de natalidade deles? Eles podem se proliferar rapidamente? Como se reproduzem?",
  str_homestory_chat_30621006 = "É semelhante aos, uh, Aurorianos...?",
  str_homestory_chat_30621007 = "Isso não pareceu que você está certo de tudo.",
  str_homestory_chat_30621008 = "Eles provavelmente não conseguem se reproduzir.",
  str_homestory_chat_30621009 = "Sério?",
  str_homestory_chat_30621010 = "Uhum. Eu nunca vi eles nascerem, como se todos surgissem do nada.",
  str_homestory_chat_30621011 = "Corrida interessante... Mas acho que não consigo ganhar dinheiro com eles.",
  str_homestory_chat_30621012 = "Espere, e se tentarmos uma abordagem diferente...? Saquei!",
  str_homestory_chat_30621013 = "Vamos ouvir isso.",
  str_homestory_chat_30621014 = "Menos significa que é raro, raro significa que é precioso, precioso significa que atrai público, público significa ingressos!",
  str_homestory_chat_30621015 = "Está pensando...",
  str_homestory_chat_30621016 = "Transforme-os em estrelas e coloque-os em programas por toda Astra!",
  str_homestory_chat_30621017 = "Vamos chamar de \"A Volta ao Mundo de uma Raça Misteriosa!\" O que acha?",
  str_homestory_chat_30621018 = "Acho que você deveria desistir agora.",
  str_homestory_chat_30621019 = "Por quê?",
  str_homestory_chat_30621020 = "Você está transformando eles em um circo de horrores...",
  str_homestory_chat_30621021 = "Isso pode ser possível.",
  str_homestory_chat_30621022 = "\"Superstar Chubbs\" é uma proposta intrigante, mas precisamos saber a opinião deles primeiro.",
  str_homestory_chat_30621023 = "Sem problemas! Me avise o que eles disserem!",
  str_homestory_chat_30622001 = "Vamos falar sobre os Jardins da Nuvem.",
  str_homestory_chat_30622002 = "Claro, eu queria discutir isso, de qualquer forma.",
  str_homestory_chat_30622003 = "O que foi?",
  str_homestory_chat_30622004 = "Desenvolvimento imobiliário. É longo na natureza e curto em conveniência.",
  str_homestory_chat_30622005 = "Sem praça de alimentação, área de compras, entretenimento... Você não consegue atrair turistas.",
  str_homestory_chat_30622006 = "Nunca quis atrair turistas... Estou bem, desde que meus amigos se sintam confortáveis aqui.",
  str_homestory_chat_30622007 = "Não! Isso pode ser sustentável por enquanto, mas já se perguntou o que vai acontecer no futuro?",
  str_homestory_chat_30622008 = "Por quanto tempo você consegue resistir depois que ficar sem receita?",
  str_homestory_chat_30622009 = "Em vez de esperar pelo futuro, você deveria se preocupar com o agora! Que tal me deixar administrar os Jardins das Nuvens, o que você diz?",
  str_homestory_chat_30622010 = "O que você quer chegar?",
  str_homestory_chat_30622011 = "Venda para mim. Eu vou transformá-lo no principal distrito comercial do mundo!",
  str_homestory_chat_30622012 = "Eu prefiro manter o status quo.",
  str_homestory_chat_30623001 = "Vamos falar sobre o seu cabelo, então.",
  str_homestory_chat_30623002 = "Meu cabelo? Não há nada para falar. É bem normal.",
  str_homestory_chat_30623003 = "Aposto que esse penteado é um grande incômodo.",
  str_homestory_chat_30623004 = "Acabei de ir a um salão de cabeleireiro. Custa apenas alguns milhares de Noitium por vez.",
  str_homestory_chat_30623005 = "Alguns milhares! O que eles fazem que é tão caro?",
  str_homestory_chat_30623006 = "Cortar, aparar, estilizar e assim por diante. Falando nisso, acabei de ter uma ideia para um projeto.",
  str_homestory_chat_30623007 = "O que foi?",
  str_homestory_chat_30623008 = "Abra um salão de cabelo aqui! Imagino que haja pessoas suficientes que precisam de um cabeleireiro por aqui, não é?",
