  str_homestory_chat_30623010 = "Um dono de salão que eu conheço acontece de ter as conexões certas...",
  str_homestory_chat_30623011 = "Estou adivinhando que você só quer arrumar seu cabelo aqui.",
  str_homestory_chat_30623012 = "Claro que consigo fazer de graça se eu possuir. Você ganha 20% de desconto, no entanto!",
