  str_homestory_chat_30623014 = "Então você concordou?! Vou começar a girar a roda amanhã!",
  str_homestory_chat_30623015 = "Espere um minuto, eu ainda estava ponderando a opção!",
  str_homestory_chat_30624001 = "Ouvi dizer que você está de olho nos Chubbs ultimamente?",
  str_homestory_chat_30624002 = "Correto. Interessado em entregá-los para mim?",
  str_homestory_chat_30624003 = "Eles não são mercadorias!",
  str_homestory_chat_30624004 = "Parou!",
  str_homestory_chat_30624005 = "Entendido. Eles assinaram um contrato com você, não é? Diga seu preço.",
  str_homestory_chat_30624006 = "Indenizações, taxas de transferência, bônus de assinatura... Evetudo é negociável.",
  str_homestory_chat_30624007 = "O que isso tem a ver com alguma coisa? Por que você quer que eles trabalhem para você de repente?",
  str_homestory_chat_30624008 = "Estou lançando um grande projeto e preciso de alguns trabalhadores competentes.",
