  str_homestory_chat_30624011 = "Eles podem ler e fazer matemática, sabem muito, não comem muito e provavelmente não dormem nada.",
  str_homestory_chat_30624012 = "Que funcionário perfeito! Não se preocupe, eu pagarei pelas horas extras!",
