  str_homestory_chat_30624014 = "Espere, eles podem não estar dispostos a fazer isso!",
  str_homestory_chat_30625001 = "Pare de pensar em projetos e tome um gole de algo.",
  str_homestory_chat_30625002 = "Mas não há nada para beber nos Jardins da Nuvem. Tudo o que vejo é água fria.",
