  str_homestory_chat_30799999 = "O que está fazendo?",
  str_homestory_chat_30721001 = "Apenas dando a rodada.",
  str_homestory_chat_30721002 = "Não consegue fazer algo mais significativo?",
  str_homestory_chat_30721003 = "Este é um hobby meu. Você provavelmente está entediado demais, no entanto.",
