  str_homestory_chat_30721005 = "Pescaria?",
  str_homestory_chat_30721006 = "Muito silencioso, e é constrangedor quando você não pega nada.",
  str_homestory_chat_30721007 = "Jardinagem?",
  str_homestory_chat_30721008 = "Vejo apenas árvores grandes e estranhas ao redor... Muito estranho para o meu gosto.",
  str_homestory_chat_30721009 = "Confira o museu.",
  str_homestory_chat_30721010 = "Não há muito para ver lá.",
  str_homestory_chat_30721011 = "Você simplesmente não se interessa por nada! Por que não tira um cochilo no seu quarto?",
  str_homestory_chat_30721012 = "Não se exalte. Eu estava apenas tentando fazer você relaxar e ficar tranquilo.",
  str_homestory_chat_30721013 = "EveToda vez que te vejo, você está fazendo a rodada ou trabalhando. Estou preocupado com você...",
  str_homestory_chat_30721014 = "A vida não se limita a expandir os Jardins da Nuvem.",
