  str_homestory_chat_30821010 = "Café.",
  str_homestory_chat_30821011 = "É um bom ânimo, mas um pouco amargo e precisa de muito açúcar...",
  str_homestory_chat_30821012 = "Risotto.",
  str_homestory_chat_30821013 = "É muito satisfatório, mas melhor com acompanhamentos.",
  str_homestory_chat_30821014 = "Tortas de frutas.",
  str_homestory_chat_30821015 = "Eu não sabia que você gostava tanto de doces.",
  str_homestory_chat_30821016 = "Você não parece muito interessado nessa comida.",
  str_homestory_chat_30821017 = "Nah, sinto falta do Deserto Rediesel sempre que falo sobre comida.",
  str_homestory_chat_30821018 = "A tempestade de areia pode ser terrível, mas a comida é agradável...",
  str_homestory_chat_30821019 = "Gosta dos sorvetes e salgadinhos de lagarto, ou vermes de rediesel fritos.",
  str_homestory_chat_30821020 = "Mayabrir um café Rediesel nos Jardins das Nuvens? Isso funcionará?",
  str_homestory_chat_30821021 = "Com certeza vai fechar as portas.",
  str_homestory_chat_30822001 = "Ei, como você está se adaptando até agora?",
  str_homestory_chat_30822002 = "Oi PlayerName! É agradável aqui, tranquilo, confortável, é apenas...",
  str_homestory_chat_30822003 = "Aqui vem a parte ruim...",
  str_homestory_chat_30822004 = "Eu continuo espirrando às vezes, tipo... Atchim!",
  str_homestory_chat_30822005 = "Eu não sei por quê, mas estou bem quando saio daqui.",
  str_homestory_chat_30822006 = "Algo no ambiente, talvez? Pólens, possivelmente?",
  str_homestory_chat_30822007 = "Atchim! Provavelmente, já que flores são raras no Deserto Rediesel.",
  str_homestory_chat_30822008 = "Tudo que você vê é areia, areia e mais areia, o que não me incomoda.",
  str_homestory_chat_30822009 = "Se entrar no meu nariz ou nos meus olhos, consigo tirar em dois tempos.",
  str_homestory_chat_30822010 = "Mas os pólens que você mencionou... Atchim! São muito irritantes!",
  str_homestory_chat_30822011 = "Tente ficar longe deles ou venha em outro momento.",
  str_homestory_chat_30822012 = "Ou aguente por alguns dias até se acostumar.",
  str_homestory_chat_30822013 = "A natureza nos Jardins das Nuvens certamente diferia do Deserto Rediesel.",
  str_homestory_chat_30822014 = "É muito relaxante e até cativante. Atchim!",
  str_homestory_chat_30823001 = "O que você tá olhando?",
  str_homestory_chat_30823002 = "Estou tentando encontrar a Águia Gigante. Onde você estacionou?",
  str_homestory_chat_30823003 = "Exterior.",
  str_homestory_chat_30823004 = "Você não está preocupado que isso possa ser perigoso?",
  str_homestory_chat_30823005 = "Ele pode se proteger. Even se não, ele pode simplesmente voar para longe.",
  str_homestory_chat_30823006 = "Por que você está procurando por ele?",
  str_homestory_chat_30823007 = "Apenas curioso para saber onde está e se pode se proteger.",
  str_homestory_chat_30823008 = "Ele está bem, não se preocupe.",
  str_homestory_chat_30823009 = "No entanto, se você está aqui, onde está o Lagarto Gigante?",
  str_homestory_chat_30823010 = "Andei de carro. O Lagarto Gigante preferiu não sair do deserto.",
  str_homestory_chat_30823011 = "Provavelmente está saindo com aqueles caras não confiáveis...",
  str_homestory_chat_30823012 = "Não é assim que se fala dos seus amigos...",
  str_homestory_chat_30999999 = "O que você está fazendo?",
  str_homestory_chat_30921001 = "Apenas dando um passeio. E você?",
  str_homestory_chat_30921002 = "Tem algo em sua mente?",
  str_homestory_chat_30921003 = "Com certeza, e você chegou bem na hora de ouvir tudo sobre isso. Eu preciso da sua opinião sobre algo.",
  str_homestory_chat_30921004 = "O que é isso...?",
  str_homestory_chat_30921005 = "Dê uma olhada nestes generais. Quem entre eles você acha que seria um bom Grande Marechal?",
  str_homestory_chat_30921006 = "Hum... Vejamos.",
  str_homestory_chat_30921007 = "Sharona.",
  str_homestory_chat_30921008 = "Hum. Não é uma má candidata. Para este trabalho, ela possui a liderança perfeita, visão estratégica e lealdade.",
  str_homestory_chat_30921009 = "Infelizmente, no entanto, ela é de Lumópolis e, mesmo tendo basicamente cortado todos os laços com sua vida passada...",
  str_homestory_chat_30921010 = "Aos olhos da \"essas pessoas\", ela ainda está longe de ser perfeita.",
  str_homestory_chat_30921011 = "Entendo...",
  str_homestory_chat_30921012 = "Barton.",
  str_homestory_chat_30921013 = "Ele é, no máximo, um general. O homem só se sente em casa quando está no campo de batalha.",
  str_homestory_chat_30921014 = "Em tempos de paz, ele acabará sendo um incômodo para o público ou se tornará um preguiçoso inútil.",
  str_homestory_chat_30921015 = "Uau, você é duro.",
  str_homestory_chat_30921016 = "Apenas dizendo a verdade.",
  str_homestory_chat_30921017 = "Hiiro.",
  str_homestory_chat_30921018 = "A coragem dela é inquestionável e ela comanda suas tropas com a máxima disciplina e autoridade. Infelizmente...",
  str_homestory_chat_30921019 = "Hiiro às vezes vai muito além de \"corajosa\" e frequentemente se perde no calor da batalha.",
  str_homestory_chat_30921020 = "Claro, é indiscutível que um soldado deve ser corajoso, mas a coragem nunca deve vir ao custo da vitória.",
  str_homestory_chat_30921021 = "Os dois nem sempre andam juntos... Não sei se você consegue perceber a diferença sutil ali.",
  str_homestory_chat_30921022 = "Acho que entendi... até certo ponto.",
  str_homestory_chat_30921023 = "Então, parece que... ninguém é realmente adequado para o papel.",
  str_homestory_chat_30921024 = "Bem, na verdade, basta olhar isso de outro ângulo: se esses candidatos tivessem adjuntos adequados, oficiais de equipe ou algo assim, para ajudá-los...",
  str_homestory_chat_30921025 = "Eles poderiam ser totalmente bons Grandes Marechais.",
  str_homestory_chat_30922001 = "Só indo ver se algum dos meus amigos está por aí.",
  str_homestory_chat_30922002 = "Falando em amigos, o que você acha da Reinhardt? Você diria que ela é uma boa amiga ou uma boa chefe?",
  str_homestory_chat_30922003 = "Ela é uma boa amiga.",
  str_homestory_chat_30922004 = "Ela é uma boa chefe.",
  str_homestory_chat_30922005 = "Por que você está me perguntando isso de repente?",
  str_homestory_chat_30922006 = "Talvez você já saiba que nós dois éramos colegas de classe.",
  str_homestory_chat_30922007 = "Ela costumava ser minha comandante... Naquela época, o desejo dela era uma ordem para mim.",
  str_homestory_chat_30922008 = "No entanto, pelo jeito como as coisas estão, eu posso me tornar seu superior no futuro.",
  str_homestory_chat_30922009 = "Entendi... Você está pensando em como se dar bem com ela, certo?",
  str_homestory_chat_30922010 = "Isso mesmo.",
  str_homestory_chat_30922011 = "Não precisa se preocupar demais com isso. Apenas siga o fluxo.",
  str_homestory_chat_30922012 = "Eu sabia que você diria isso, mas ainda assim considero um bom conselho no meu ponto de vista.",
  str_homestory_chat_30922013 = "Obrigada, PlayerName.",
  str_homestory_chat_30923001 = "Só quero ir fazer uma pausa.",
  str_homestory_chat_30923002 = "O que você costuma fazer para relaxar?",
  str_homestory_chat_30923003 = "Dar um passeio.",
  str_homestory_chat_30923004 = "Parece bem básico.",
  str_homestory_chat_30923005 = "Vamos pescar.",
  str_homestory_chat_30923006 = "Isso é tão clichê.",
  str_homestory_chat_30923007 = "Ouvi dizer que os Celestitas desenvolveram um método único de relaxamento chamado \"meditação.\"",
  str_homestory_chat_30923008 = "Pessoalmente, eu raramente medito... Por que você se interessou por meditação de repente?",
  str_homestory_chat_30923009 = "Quer tentar?",
  str_homestory_chat_30923010 = "A meditação é uma forma de relaxamento e também de treinamento.",
  str_homestory_chat_30923011 = "Ao relaxar, você pode encontrar seu verdadeiro caminho e reforçar a trajetória do seu progresso.",
  str_homestory_chat_30923012 = "Este método de treinamento é crucial para mim - ajuda a recarregar minhas \"baterias\", por assim dizer.",
  str_homestory_chat_30923013 = "Vou tentar mais tarde...",
  str_homestory_chat_30924001 = "Apenas andando.",
  str_homestory_chat_30924002 = "Parece que isso realmente combina com você, essa história de caminhar.",
  str_homestory_chat_30924003 = "Por que diz isso?",
  str_homestory_chat_30924004 = "Porque você está incrível! O segredo está em todas essas caminhadas, certo?",
  str_homestory_chat_30924005 = "Não.",
  str_homestory_chat_30924006 = "Qual é o seu segredo, então?",
  str_homestory_chat_30924007 = "Nada secreto. Apenas ter um sono tranquilo e manter uma vida saudável e equilibrada.",
  str_homestory_chat_30924008 = "Bem, você, ao contrário, está sempre com aparência abatida... Será porque costuma ficar acordado até tarde? Não se mate por causa do trabalho.",
  str_homestory_chat_30924009 = "Você poderia dizer que é o preço da responsabilidade.",
  str_homestory_chat_30925001 = "Apenas patrulhando Cloud Gardens.",
  str_homestory_chat_30925002 = "Que azar. Não há descanso para os ímpios, né?",
  str_homestory_chat_30925003 = "Nah... Um bom passeio era exatamente o que eu precisava.",
  str_homestory_chat_30925004 = "Sério? Então é assim que você administra o Cloud Gardens, né?",
  str_homestory_chat_30925005 = "Mais ou menos. Os Chubbs cuidam da maior parte do trabalho, enquanto eu apenas dou uma olhada de vez em quando.",
  str_homestory_chat_30925006 = "Nossa, como eu queria que administrar Illumina fosse tão simples quanto administrar Cloud Gardens.",
  str_homestory_chat_30925007 = "Eles são tão diferentes, né?",
  str_homestory_chat_30925008 = "Afinal, a Federação Illumina é responsável por combater os Eclipsitas invasores...",
  str_homestory_chat_30925009 = "E é obviamente muito maior do que Cloud Gardens...",
  str_homestory_chat_30925010 = "Isso mesmo.",
  str_homestory_chat_30925011 = "Você deveria aprender a deixar de lado um pouco dessa pressão. Agora que você está em Cloud Gardens, apenas relaxe e divirta-se aqui.",
  str_homestory_chat_31099999 = "Noite Branca nas alturas. Como está indo seu dia até agora?",
  str_homestory_chat_31001001 = "Ah, nada especial.",
  str_homestory_chat_31001002 = "Isso é uma coisa boa. Significa que a paz foi preservada aqui.",
  str_homestory_chat_31001003 = "É claro que você realmente ama dias como este.",
  str_homestory_chat_31001004 = "Todos em Crepúsculo vivem uma vida de estresse.",
  str_homestory_chat_31001005 = "Fisicamente e espiritualmente...",
  str_homestory_chat_31001006 = "Os Eclipsitas estão tão próximos do perímetro da cidade que os moradores quase podem sentir a respiração deles em suas nuques.",
  str_homestory_chat_31001007 = "Então, ao chegar aqui, não podemos deixar de nos maravilhar com a serenidade do lugar.",
  str_homestory_chat_31001008 = "Se essa paz pudesse se espalhar por todo o continente, que coisa maravilhosa seria.",
  str_homestory_chat_31021001 = "Muito bem. E você?",
  str_homestory_chat_31021002 = "Eu estava pensando... Como você considera pessoalmente as várias regiões do mundo?",
  str_homestory_chat_31021003 = "Tais como...?",
  str_homestory_chat_31021004 = "Hmm... Lumópolis.",
  str_homestory_chat_31021005 = "É o centro da civilização.",
  str_homestory_chat_31021006 = "Soberano do continente.",
  str_homestory_chat_31021007 = "O que você acha de Lumópolis?",
  str_homestory_chat_31021008 = "É o... centro da civilização, não?",
  str_homestory_chat_31021009 = "Algo no seu tom me diz que você não está tão certo disso.",
  str_homestory_chat_31021010 = "Isso ocorre porque eu moro em Crepúsculo há tanto tempo e raramente me aventuro em Lumópolis.",
  str_homestory_chat_31021011 = "O que você acha da Federação Illumina então, PlayerName?",
  str_homestory_chat_31021012 = "É a linha de frente da luta contra os Eclipsitas.",
  str_homestory_chat_31021013 = "É uma organização unida.",
  str_homestory_chat_31021014 = "Por que você está me perguntando sobre isso?",
  str_homestory_chat_31021015 = "Quando penso no que está acontecendo em Crepúsculo, não consigo deixar de me preocupar com o futuro de Crepúsculo.",
  str_homestory_chat_31021016 = "Essas pessoas da cidade... O que vai acontecer com elas?",
  str_homestory_chat_31021017 = "Você costuma pensar nessas coisas?",
  str_homestory_chat_31021018 = "Com uma vida em Crepúsculo, não tenho escolha a não ser pensar nessas coisas...",
  str_homestory_chat_31021019 = "Espero que o todo-poderoso Deus da Luz atenda às minhas preces e conceda refúgio aos moradores da cidade.",
  str_homestory_chat_31022001 = "Apenas vou dar uma volta por um tempo.",
  str_homestory_chat_31022002 = "Parece que você finalmente está pronto para aproveitar seu tempo de lazer.",
  str_homestory_chat_31022003 = "Acho que sim. O que você está fazendo agora?",
  str_homestory_chat_31022004 = "Ainda não decidi. Depois que cheguei em Cloud Gardens, me senti um pouco deslocado.",
  str_homestory_chat_31022005 = "Por que diz isso?",
  str_homestory_chat_31022006 = "Cloud Gardens é tão diferente de Crepúsculo - um lugar onde você deve empunhar sua espada quase todos os dias para sobreviver...",
  str_homestory_chat_31022007 = "Lutando contra Eclipsitas?",
  str_homestory_chat_31022008 = "Exatamente.",
  str_homestory_chat_31022009 = "Sempre me perguntei como seria a vida se eu não precisasse portar armas todos os dias?",
  str_homestory_chat_31022010 = "E agora você pode experimentar essa vida em primeira mão.",
  str_homestory_chat_31022011 = "Ah... Seria incrível se todos em Crepúsculo pudessem viver assim.",
  str_homestory_chat_31023001 = "Coisas normais. O que você está fazendo por aqui?",
  str_homestory_chat_31023002 = "Estou absorvendo vestígios de luz.",
