  str_homestory_chat_31023004 = "Não, na verdade estou rezando.",
  str_homestory_chat_31023005 = "Orando?",
  str_homestory_chat_31023006 = "Porque a Luz é minha fé...",
  str_homestory_chat_31023007 = "Ao contrário do Crepúsculo, os Jardins das Nuvens raramente veem um céu nublado.",
  str_homestory_chat_31023008 = "Estando aqui neste lugar maravilhoso, não consigo evitar sentir um desejo de invocação crescendo em meu coração.",
  str_homestory_chat_31023009 = "Ok. Vá em frente e ore... Vou deixar você com isso.",
  str_homestory_chat_31199999 = "O que você tá fazendo, Navegador?",
  str_homestory_chat_31121001 = "Ei Antony, estou planejando sair...",
  str_homestory_chat_31121002 = "Para explorar algumas ruínas.",
  str_homestory_chat_31121003 = "Ruínas? Você quer dizer do tipo inexplorado?",
  str_homestory_chat_31121004 = "Posso ir com vocês?",
  str_homestory_chat_31121005 = "Claro, por que não?",
