  str_homestory_chat_31121009 = "Mas às vezes, até mesmo uma simples pedra pode guardar segredos vitais.",
  str_homestory_chat_31121010 = "Bem, com seu grande cérebro nos guiando, talvez tenhamos uma chance de encontrar algo especial.",
  str_homestory_chat_31121011 = "Para descansar um pouco.",
  str_homestory_chat_31121012 = "Descansar? Então eu sei o lugar perfeito para você.",
  str_homestory_chat_31121013 = "Ouvi dizer que há algumas ruínas por perto.",
  str_homestory_chat_31121014 = "Ruínas adornadas com muitas pinturas rupestres misteriosas.",
  str_homestory_chat_31121015 = "Como isso tem alguma relação com eu tentar descansar?",
  str_homestory_chat_31121016 = "Com certeza!",
  str_homestory_chat_31121017 = "Deitado nas ruínas, olhando para as pinturas...",
  str_homestory_chat_31121018 = "Parece que você voltou no tempo para aquela época.",
  str_homestory_chat_31121019 = "Para mim, isso conta como uma forma de relaxar.",
  str_homestory_chat_31121020 = "Pinturas na parede, você diz? Bem, agora você chamou minha atenção.",
  str_homestory_chat_31121021 = "Então vou me preparar para a viagem.",
  str_homestory_chat_31121022 = "Claro. Te vejo daqui a pouco.",
