  str_homestory_chat_31122008 = "Especificamente, é aumentar a produção real através das seguintes equações...",
  str_homestory_chat_31122009 = "Ah, acabei de lembrar que tenho algo para fazer...",
  str_homestory_chat_31122010 = "Tenho que ir agora. Vejo você por aí.",
  str_homestory_chat_31123001 = "Apenas saindo.",
  str_homestory_chat_31123002 = "Talvez vá ver outros Aurorianos mais tarde.",
  str_homestory_chat_31123003 = "Falando de outros Aurorianos, o que você acha do No. 33, Navegador?",
  str_homestory_chat_31123004 = "Um companheiro muito bom.",
  str_homestory_chat_31123005 = "É verdade.",
  str_homestory_chat_31123006 = "No entanto, você não acha maravilhoso que ela tenha nascido em tempos antigos?",
  str_homestory_chat_31123007 = "Ah, você não está querendo estudá-la, está?",
  str_homestory_chat_31123008 = "Ah, não. Eu só quero estudar o capacete dela, só isso...",
  str_homestory_chat_31123009 = "Uma garota enigmática?",
  str_homestory_chat_31123010 = "Você também se sente assim! Entendi.",
  str_homestory_chat_31123011 = "É difícil para um Aurorian nascido na antiguidade não chamar a atenção.",
  str_homestory_chat_31123012 = "Ah, você não está querendo estudá-la, está?",
  str_homestory_chat_31123013 = "Ah, não. Eu só quero estudar o capacete dela, só isso...",
  str_homestory_chat_31123014 = "Então, por que não ir falar com ela você mesmo?",
  str_homestory_chat_31123015 = "Ela deve ser capaz de responder à maioria das suas perguntas.",
  str_homestory_chat_31124001 = "Vou ler um livro.",
  str_homestory_chat_31124002 = "Que coincidência, Navegador.",
