  str_homestory_chat_31124004 = "Qual livro você está lendo, Antony?",
  str_homestory_chat_31124005 = "Erros e Desvios nas Trajetórias Estelares.",
  str_homestory_chat_31124006 = "Um... Que profundo...",
  str_homestory_chat_31124007 = "Na verdade, não é difícil. Você vai entender quando ler, Navegador.",
  str_homestory_chat_31124008 = "Vou tentar...",
