  str_homestory_chat_31125006 = "Organizar os itens na ordem de necessidade.",
  str_homestory_chat_31125007 = "Os mais importantes ficam em cima. Aqueles que quase não são necessários vão para o fundo.",
  str_homestory_chat_31125008 = "Eficiência.",
  str_homestory_chat_31125009 = "Concordo.",
  str_homestory_chat_31125010 = "Quando organizo minha mochila, também dou ênfase à eficiência.",
  str_homestory_chat_31125011 = "Deixe-me te ajudar a arrumar o quarto.",
  str_homestory_chat_31125012 = "Tudo bem. Obrigado pela ajuda.",
  str_homestory_chat_31299999 = "Algum plano para hoje?",
  str_homestory_chat_31221001 = "Ainda não decidi...",
  str_homestory_chat_31221002 = "E você?",
  str_homestory_chat_31221003 = "Praticar Luminatics, é claro.",
  str_homestory_chat_31221004 = "Você diz isso todas as vezes. Parece pra mim que você está trabalhando demais.",
  str_homestory_chat_31221005 = "Você pode relaxar de vez em quando, sabia?",
  str_homestory_chat_31221006 = "Não é bom ficar tenso como uma corda de arco o tempo todo.",
  str_homestory_chat_31221007 = "Isso está certo...?",
  str_homestory_chat_31222001 = "Vou patrulhar o dia inteiro...",
  str_homestory_chat_31222002 = "Você realmente não tem facilidade, Navegador.",
  str_homestory_chat_31222003 = "Tão ocupado todos os dias.",
  str_homestory_chat_31222004 = "Por favor, me avise se precisar da minha ajuda em qualquer coisa!",
  str_homestory_chat_31222005 = "Bem, não há nada com que eu precise de ajuda...",
  str_homestory_chat_31222006 = "Deixa eu pensar sobre isso...",
  str_homestory_chat_31222007 = "Ah, tenho uma ideia.",
