  str_homestory_chat_31222009 = "Colocando cubos de gelo nas partes certas para relaxar o corpo...",
  str_homestory_chat_31222010 = "Isso parece um trabalho que posso fazer facilmente!",
  str_homestory_chat_31222011 = "Sinto um pouco de medo quando você está fazendo isso.",
  str_homestory_chat_31222012 = "O quê? Você não quis dizer agradável?!",
  str_homestory_chat_31222013 = "No entanto, quando terminar a patrulha...",
