  str_homestory_chat_31921020 = "Impossível! Mas tudo bem, estarei aqui quando você mudar de ideia.",
  str_homestory_chat_31922001 = "Estou apenas girando os polegares agora.",
  str_homestory_chat_31922002 = "Quer dizer, você está entediado porque não tem nada para fazer?",
  str_homestory_chat_31922003 = "Pode-se dizer que sim.",
  str_homestory_chat_31922004 = "Então, que tal jogar um jogo comigo?",
  str_homestory_chat_31922005 = "Jogo? Que jogo?",
  str_homestory_chat_31922006 = "Um muito simples.",
  str_homestory_chat_31922007 = "Eu tenho um Noitium aqui que vou jogar no ar.",
  str_homestory_chat_31922008 = "E depois?",
  str_homestory_chat_31922009 = "Vamos adivinhar se vai cair com a face para cima ou para baixo.",
  str_homestory_chat_31922010 = "Se você estiver certo, a moeda é sua.",
  str_homestory_chat_31922011 = "E se eu estiver errado?",
  str_homestory_chat_31922012 = "Então você está errado.",
  str_homestory_chat_31922013 = "Hã?",
  str_homestory_chat_31922014 = "Isso significa que tudo bem se você adivinhou errado. Sem complicações.",
  str_homestory_chat_31922015 = "Isso não funcionaria apenas a meu favor?",
  str_homestory_chat_31922016 = "Sim, mas é apenas um Noitium.",
  str_homestory_chat_31922017 = "O que conseguimos com isso supera em muito o valor nominal, e eu posso não perder, certo?",
  str_homestory_chat_31923001 = "Estou revisando o livro-razão.",
  str_homestory_chat_31923002 = "Há algum problema com isso? Posso ajudar se necessário.",
  str_homestory_chat_31923003 = "Você se importaria de dar uma olhada então?",
  str_homestory_chat_31923004 = "Claro, o prazer é todo meu.",
  str_homestory_chat_31923005 = "Deixe-me tirar o peso da sua mão...",
  str_homestory_chat_31923006 = "Entendi. O livro-razão está bastante mal mantido e organizado.",
  str_homestory_chat_31923007 = "Eu não quero te incomodar...",
  str_homestory_chat_31923008 = "Está bem, eu entendo. Mas, para ser honesto, o livro-razão é vital para qualquer instituição.",
  str_homestory_chat_31923009 = "Tenho experiência suficiente na gestão de contas, posso fazer algumas sugestões?",
  str_homestory_chat_31923010 = "Sério? Qualquer sugestão da Senhora Sheol seria de grande ajuda para mim!",
  str_homestory_chat_31923011 = "Obrigada!",
  str_homestory_chat_31923012 = "Heheh, de nada.",
  str_homestory_chat_31923013 = "São apenas pequenas dicas e sugestões.",
  str_homestory_chat_31923014 = "Deve ser o mais detalhado possível em cada entrada, mas também conciso.",
  str_homestory_chat_31923015 = "É desnecessário dizer que as datas e os propósitos devem ser listados em colunas separadas. Além disso, registrar os valores em dois formatos pode reduzir a chance de erros.",
  str_homestory_chat_31923016 = "Desse jeito, é muito mais fácil revisar.",
  str_homestory_chat_31923017 = "Entendi.",
  str_homestory_chat_31923018 = "Ah, uma coisinha...",
  str_homestory_chat_31923019 = "Espere! Eu preciso anotar isso!",
  str_homestory_chat_31924001 = "Estou com sede e quero algo para beber.",
  str_homestory_chat_31924002 = "Que tal um café?",
  str_homestory_chat_31924003 = "Café?",
  str_homestory_chat_31924004 = "Sim, acabei de comprar alguns grãos de café bem legais.",
  str_homestory_chat_31924005 = "Seria ótimo obter uma segunda opinião.",
  str_homestory_chat_31924006 = "Mas eu não sei muito sobre café...",
  str_homestory_chat_31924007 = "Tudo bem. Apenas me dê suas impressões após bebê-lo.",
  str_homestory_chat_31924008 = "Não me importo de tentar se é isso que é preciso.",
  str_homestory_chat_31924009 = "Você gosta de café, Senhora Sheol?",
  str_homestory_chat_31924010 = "Não particularmente, mas também não odeio.",
  str_homestory_chat_31924011 = "Então, por que você comprou os grãos em vez de café moído?",
  str_homestory_chat_31924012 = "Sem motivo especial. Os grãos de café são um dos muitos negócios da Guilda Cloudrover, de qualquer forma.",
  str_homestory_chat_31924013 = "Acabei de sentir o desejo de provar isso por mim mesmo.",
  str_homestory_chat_31925001 = "É hora de eu estudar a seguir.",
  str_homestory_chat_31925002 = "Hora de estudar?",
  str_homestory_chat_31925003 = "Em outras palavras, leia livros.",
  str_homestory_chat_31925004 = "Entendi. May Posso perguntar que tipo de livros você está planejando ler?",
  str_homestory_chat_31925005 = "História e geografia.",
  str_homestory_chat_31925006 = "Também sei um pouco sobre esses assuntos. May Posso fazer recomendações para você?",
  str_homestory_chat_31925007 = "Você é conhecedora nesses campos, Senhora Sheol?",
  str_homestory_chat_31925008 = "Como comerciante, quanto mais eu sei, melhor. Assim, posso conversar com clientes de diferentes ramos.",
  str_homestory_chat_31925009 = "Vejo que é preciso trabalhar duro para ser um grande comerciante.",
  str_homestory_chat_31925010 = "Economia.",
  str_homestory_chat_31925011 = "Ah é? Você se interessa por economia?",
  str_homestory_chat_31925012 = "Não tanto interessado, mas curioso.",
  str_homestory_chat_31925013 = "Sem mencionar que é sempre melhor ler mais livros.",
  str_homestory_chat_31925014 = "Isso mesmo.",
  str_homestory_chat_31925015 = "Tenho muitos bons livros da minha coleção pessoal que posso recomendar.",
  str_homestory_chat_31925016 = "Por favor, passe por aqui alguma vez.",
  str_homestory_chat_32099999 = "Quero reformar meu escritório! Qual estilo você acha que funciona melhor?",
  str_homestory_chat_32021001 = "Estilo Northland!",
  str_homestory_chat_32021002 = "Oh? Bem, grande parte de Northland realmente parece algo saído de um conto de fadas, especialmente suas decorações e arquitetura.",
  str_homestory_chat_32021003 = "Eu não percebi que você era tão romântico.",
  str_homestory_chat_32021004 = "Você é um cientista.",
  str_homestory_chat_32021005 = "Ideias românticas como essa provavelmente te incomodam, certo?",
  str_homestory_chat_32021006 = "Você é da Federação Illumina.",
  str_homestory_chat_32021007 = "Isso não significa que você é contra ideias impraticáveis e românticas como essa?",
  str_homestory_chat_32021008 = "Que monumental mal-entendido!",
  str_homestory_chat_32021009 = "É verdade que eu sou um cientista da Federação Illumina...",
  str_homestory_chat_32021010 = "Então é natural para todos acreditarem que eu não quero nada com romantismo.",
  str_homestory_chat_32021011 = "Mas acredito que essa é uma visão muito limitada da noção.",
  str_homestory_chat_32021012 = "Para tornar o desconhecido compreensível, para transformar desertos em cidades...",
  str_homestory_chat_32021013 = "Isso também não é romântico à sua maneira?",
  str_homestory_chat_32021014 = "Acho que isso faz sentido.",
  str_homestory_chat_32021015 = "Não sabia que você também era um debatedor eloquente.",
  str_homestory_chat_32021016 = "Também sou alguém muito bom em aceitar sugestões.",
  str_homestory_chat_32021017 = "É por isso que decidi redecorar meu escritório no estilo de Northland!",
  str_homestory_chat_32022001 = "Estilo Lumópolis!",
  str_homestory_chat_32022002 = "O estilo de Lumopolis tem uma sensação muito clássica e piedosa.",
  str_homestory_chat_32022003 = "Com todos os cabos e maquinários passando pelo meu escritório, não tenho certeza se esse estilo de decoração seria uma boa combinação...",
  str_homestory_chat_32022004 = "Mas sua personalidade está cheia de contradições.",
  str_homestory_chat_32022005 = "O contraste nítido é o que faz dele uma combinação perfeita!",
  str_homestory_chat_32022006 = "Coisas descombinadas também têm um certo charme.",
  str_homestory_chat_32022007 = "Quem diz que as coisas precisam combinar para serem bonitas?",
  str_homestory_chat_32022008 = "Hahahaha! Você faz um bom ponto!",
  str_homestory_chat_32022009 = "Seu conhecimento e perspicácia são qualidades extremamente admiráveis.",
  str_homestory_chat_32022010 = "Eles poderiam ter surgido das suas inúmeras viagens pelo mundo?",
  str_homestory_chat_32022011 = "Tenho certeza que também é porque nos conhecemos há tanto tempo...",
  str_homestory_chat_32022012 = "Vou levar isso como um elogio!",
  str_homestory_chat_32023001 = "Estilo Umbraton!",
  str_homestory_chat_32023002 = "Que sugestão complicada para oferecer.",
  str_homestory_chat_32023003 = "Então me diga, como você definiria exatamente o estilo de Umbraton?",
  str_homestory_chat_32023004 = "Na minha experiência, Umbraton tende a enfatizar a diversidade.",
  str_homestory_chat_32023005 = "Essa é a beleza disso. Você não vê...?",
  str_homestory_chat_32023006 = "Pode até parecer uma sugestão aleatória, mas quando você realmente pensa sobre isso...",
  str_homestory_chat_32023007 = "É a ideia perfeita que engloba todas as sugestões!",
  str_homestory_chat_32023008 = "Na verdade, você não terá que se preocupar em redecorar seu escritório nunca mais! Nem nos próximos cinquenta anos!",
  str_homestory_chat_32023009 = "Uau... Às vezes, minhas ideias são tão boas que até me surpreendo!",
  str_homestory_chat_32023010 = "Você está apenas inventando desculpas porque não conseguiu pensar em uma ideia melhor, não é?",
  str_homestory_chat_32023011 = "Hehe... Eu me entreguei?",
  str_homestory_chat_32023012 = "Deixa pra lá. Suponho que sou parcialmente culpado por você ter acabado assim, então não vou insistir no assunto.",
  str_homestory_chat_32023013 = "Então você sabia o tempo todo!",
  str_homestory_chat_32023014 = "Sou um gênio em todos os sentidos da palavra. Nunca se esqueça disso.",
  str_homestory_chat_32024001 = "Estilo Longzhou!",
  str_homestory_chat_32024002 = "Uau, não acredito que você sugeriu isso...",
  str_homestory_chat_32024003 = "Sempre fui fascinado pelo estilo de decoração daquela terra distante...",
  str_homestory_chat_32024004 = "Mas você tem alguma ideia de quanto isso custaria?",
  str_homestory_chat_32024005 = "Mesmo algo tão simples quanto uma cadeira de madeira...",
  str_homestory_chat_32024006 = "Custaria o mesmo que redecorar todo o meu escritório uma vez!",
  str_homestory_chat_32024007 = "Esse tipo de luxo sempre estará fora do alcance para pessoas normais como nós, meu amigo celestita.",
  str_homestory_chat_32024008 = "\"Pessoas normais\"?",
  str_homestory_chat_32024009 = "Eu nunca esperava ouvir você se referindo a si mesmo como uma pessoa \"normal\" em minha vida...",
  str_homestory_chat_32024010 = "Ou para se colocar no meu nível, aliás...",
  str_homestory_chat_32024011 = "Obrigado, Longzhou!",
  str_homestory_chat_32024012 = "É realmente tão caro?",
  str_homestory_chat_32024013 = "Eu não sabia que os móveis de Longzhou eram tão caros...",
  str_homestory_chat_32024014 = "Perdoe-me, Longzhou!",
  str_homestory_chat_32024015 = "... Ah, obrigado por me lembrar que nunca vou realizar meus sonhos de um escritório ao estilo de Longzhou.",
  str_homestory_chat_32024016 = "Agora me compense pelo meu sofrimento mental!",
  str_homestory_chat_32024017 = "M-Mas eu não tenho dinheiro!",
  str_homestory_chat_32025001 = "Estilo celestita!",
  str_homestory_chat_32025002 = "Então o seu próprio estilo? Que resposta verdadeiramente inesperada.",
  str_homestory_chat_32025003 = "Eu me referia ao estilo do meu povo, não ao meu próprio...",
  str_homestory_chat_32025004 = "Então, você estaria disposto a redecorar meu escritório pessoalmente?",
  str_homestory_chat_32025005 = "Como você tirou essa ideia da minha sugestão?!",
  str_homestory_chat_32025006 = "Bem, neste mundo—",
  str_homestory_chat_32025007 = "O único familiarizado com o estilo dos Celestitas não é outro senão você mesmo.",
  str_homestory_chat_32025008 = "V-Você não precisava ter dito dessa maneira!",
  str_homestory_chat_32025009 = "Além disso, existem muitos historiadores e arqueólogos em Lumópolis e na Federação Illumina que podem te ajudar...",
  str_homestory_chat_32025010 = "Tenho certeza de que eles sabem tudo sobre o estilo dos Celestitas.",
  str_homestory_chat_32025011 = "Sim, mas por que eu iria querer a ajuda deles em vez da sua...",
  str_homestory_chat_32025012 = "Você pode me dar, digamos, ao menos uma razão?",
  str_homestory_chat_32025013 = "... Não posso.",
  str_homestory_chat_32025014 = "Mas eu consigo pensar em três boas razões pelas quais você quer a minha ajuda.",
  str_homestory_chat_32025015 = "Um, eu sou barato. Dois, não vou cobrar tanto. E três, vou te economizar dinheiro...",
  str_homestory_chat_32025016 = "Hahahaha! Você não deveria se subestimar tanto, sabia?",
  str_homestory_chat_32025017 = "Estou perguntando porque sabia que você faria um ótimo trabalho decorando meu escritório.",
  str_homestory_chat_32025018 = "E também porque eu gosto tanto de conversar com você.",
  str_homestory_chat_32025019 = "Isso é tudo!",
  str_homestory_chat_32199999 = "O que você deseja pedir?",
  str_homestory_chat_32121001 = "Paz mundial.",
  str_homestory_chat_32121002 = "Uau, para alguém fazer um desejo altruísta assim—",
  str_homestory_chat_32121003 = "Você simplesmente não está levando isso a sério...",
  str_homestory_chat_32121004 = "Ou você realmente quer algo tão grandioso.",
  str_homestory_chat_32121005 = "Então, qual se aplica a você, PlayerName?",
  str_homestory_chat_32121006 = "Não levando a sério.",
  str_homestory_chat_32121007 = "Haha, isso realmente combina com seu estilo.",
  str_homestory_chat_32121008 = "Você nunca foi de deixar o futuro apenas nas mãos de esperanças e desejos. Quando você realmente quer algo, você o persegue e o torna realidade...",
  str_homestory_chat_32121009 = "Eu quero algo tão grandioso.",
  str_homestory_chat_32121010 = "Em outras palavras, a paz mundial é seu verdadeiro objetivo nesta vida.",
  str_homestory_chat_32121011 = "Você faz de tudo para garantir que cada passo que dá te aproxima mais desse sonho...",
  str_homestory_chat_32121012 = "Em todos os meus milhares de anos, pessoas como você sempre me dão as maiores dores de cabeça.",
  str_homestory_chat_32121013 = "Huh? Por quê?",
  str_homestory_chat_32121014 = "Porque pessoas como você também são aquelas que acabam mudando o mundo.",
  str_homestory_chat_32122001 = "Paz e segurança para aqueles que me são queridos.",
  str_homestory_chat_32122002 = "Ouço esse tipo de desejo no meu templo o tempo todo.",
  str_homestory_chat_32122003 = "Isso me faz pensar, as pessoas que fazem esse tipo de desejo são felizes ou apenas infelizes?",
  str_homestory_chat_32122004 = "Feliz, claro!",
  str_homestory_chat_32122005 = "Isso significa que eles mantêm seus amigos e entes queridos em seus corações e também querem que eles sejam felizes...",
  str_homestory_chat_32122006 = "Como eles poderiam ser possivelmente infelizes?",
  str_homestory_chat_32122007 = "Porque a felicidade é passageira.",
  str_homestory_chat_32122008 = "...!",
  str_homestory_chat_32122009 = "A única razão pela qual as pessoas fazem esse tipo de desejo é porque elas estão cientes disso, você não acha?",
  str_homestory_chat_32122010 = "... Você tem razão.",
  str_homestory_chat_32122011 = "Em um mundo dominado por Eclipsitas, estamos sempre em risco de encontrar infortúnios inesperados.",
  str_homestory_chat_32122012 = "É por isso que quero fazer tudo o que posso para garantir que meus amigos estejam seguros.",
  str_homestory_chat_32122013 = "Mesmo que seja algo tão insignificante quanto fazer um desejo por eles.",
  str_homestory_chat_32122014 = "Heh. O universo é impermanente, e ainda assim, as pessoas frequentemente encontram força e significado por causa disso.",
  str_homestory_chat_32122015 = "Essa é precisamente a razão pela qual tenho tanto respeito e admiração pelos mortais.",
  str_homestory_chat_32123001 = "Para visitar todos os cantos do mundo.",
  str_homestory_chat_32123002 = "Oh? Isso não é um desejo que eu ouço todos os dias, PlayerName.",
  str_homestory_chat_32123003 = "Você já é mais do que capaz de fazer isso, então por que fazer um desejo disso?",
  str_homestory_chat_32123004 = "Será que algo está no caminho?",
  str_homestory_chat_32123005 = "Eu não tenho dinheiro.",
  str_homestory_chat_32123006 = "\"Há aqueles que vivem pelo lazer, mas as circunstâncias da vida negam sua alegria.\"",
  str_homestory_chat_32123007 = "Mas isso é fácil de resolver! Basta pegar algumas das minhas joias e penhorá-las por algum dinheiro!",
  str_homestory_chat_32123008 = "Há monstros demais.",
  str_homestory_chat_32123009 = "\"Um urso bloqueia o caminho enquanto tigres e leopardos rugem ao nosso lado.\"",
  str_homestory_chat_32123010 = "Mas certamente até os Eclipsitas mais resistentes não são páreo para você comigo ao seu lado, certo?",
  str_homestory_chat_32123011 = "A propósito, PlayerName, você entende o significado dos meus poemas?",
  str_homestory_chat_32123012 = "Sim, ouvi muitos deles enquanto viajava por Longzhou.",
  str_homestory_chat_32123013 = "Quanto mais eu os via e ouvia, mais eles começavam a fazer sentido.",
  str_homestory_chat_32123014 = "Você realmente sabe como aprender com suas viagens, PlayerName!",
  str_homestory_chat_32123015 = "Obrigada!",
  str_homestory_chat_32123016 = "De qualquer forma, você é um querido amigo meu agora. Eu não posso deixar você fazer todo o trabalho pesado, sabe.",
  str_homestory_chat_32123017 = "É por isso que vou continuar viajando pelo mundo e melhorando o máximo possível!",
  str_homestory_chat_32123018 = "Bom, bom! Estarei te esperando.",
  str_homestory_chat_32124001 = "Para se esconder na Colossus para sempre.",
  str_homestory_chat_32124002 = "Eu entendo completamente! Não há nada mais confortável do que se aconchegar em seu próprio pequeno ninho.",
  str_homestory_chat_32124003 = "Certo? Às vezes, uma estadia em casa é exatamente o que precisamos!",
  str_homestory_chat_32124004 = "Especialmente quando está frio e nevando lá fora, como no inverno...",
  str_homestory_chat_32124005 = "Não há nada como se aconchegar em casa com uma bebida quente e um bom livro...",
  str_homestory_chat_32124006 = "Você realmente faz tudo isso?",
  str_homestory_chat_32124007 = "Geralmente, eu apenas durmo o tempo todo.",
  str_homestory_chat_32124008 = "Você deve tentar da próxima vez.",
  str_homestory_chat_32124009 = "Bem, parece interessante!",
  str_homestory_chat_32124010 = "Hmm... Primeiro, vou ter que arranjar um cobertor grande e agradável para mim!",
  str_homestory_chat_32124011 = "Talvez eu faça do seu jeito na próxima vez.",
  str_homestory_chat_32124012 = "Ok! Nós podemos até fazer isso juntos!",
  str_homestory_chat_32124013 = "Assim, você pode me acordar em um horário razoável!",
  str_homestory_chat_32124014 = "Eu nunca soube que os desejos do seu coração eram tão simples, PlayerName.",
  str_homestory_chat_32124015 = "A princípio, pensei que você gostaria de trazer seu povo de volta, ou algo assim...",
  str_homestory_chat_32124016 = "É tarde demais para mudar coisas assim...",
  str_homestory_chat_32124017 = "Além disso, um desejo deve ser usado para melhorar nossas vidas e as vidas de nossos amigos, certo?",
  str_homestory_chat_32124018 = "Exatamente. Aceitar que o passado está concluído é ser corajoso.",
  str_homestory_chat_32125001 = "Para você ser feliz para sempre!",
  str_homestory_chat_32125002 = "Hã? Você realmente desperdiçaria um desejo único na vida em mim assim?",
  str_homestory_chat_32125003 = "Por quê?",
  str_homestory_chat_32125004 = "Porque os desejos devem ser feitos pelo bem de nossos amigos e familiares!",
  str_homestory_chat_32125005 = "Além disso, é melhor lutar pelas coisas que você quer do que simplesmente desejá-las.",
  str_homestory_chat_32125006 = "... Hahaha, eu sempre quis dizer isso! Soou bem legal, certo?",
  str_homestory_chat_32125007 = "... Funcionou.",
  str_homestory_chat_32125008 = "Não precisa rir disso também. Eu nunca tiraria sarro de você por isso.",
  str_homestory_chat_32125009 = "Talvez eu também devesse fazer um desejo?",
  str_homestory_chat_32125010 = "Oh? Uma deusa fazendo um desejo, huh? Acho que sempre há uma primeira vez para tudo!",
  str_homestory_chat_32125011 = "À luz do sol e da lua e à força dos rios e oceanos.",
  str_homestory_chat_32125012 = "May meu amigo PlayerName desfrute da força do corpo, descanso tranquilo e alegria nos dias que virão.",
  str_homestory_chat_32125013 = "E-Eu ouvi meu nome agora mesmo...?",
  str_homestory_chat_32125014 = "Em outras palavras, desejo-lhe boa saúde, boa comida, bom sono...",
  str_homestory_chat_32125015 = "E um muito feliz ano novo!",
  str_homestory_chat_32125016 = "Uau...",
  str_homestory_chat_32125017 = "Agora podemos ter mais um ano feliz juntos.",
  str_homestory_chat_32125018 = "Confie em mim, o desejo de um dragão nunca deve ser levado na brincadeira.",
  str_homestory_chat_32125019 = "E-Entendi! Além disso...",
  str_homestory_chat_32125020 = "Obrigado, Chen'ni.",
  str_homestory_chat_32299999 = "O que você está fazendo, PlayerName?",
  str_homestory_chat_32221001a = "Hum...",
  str_homestory_chat_32221001 = "Vou passar o dia na cama.",
  str_homestory_chat_32221002 = "O dia todo? Você me lembra um dos meus discípulos seniores.",
  str_homestory_chat_32221003 = "Seu discípulo sênior?",
  str_homestory_chat_32221004 = "Sim. Ele costumava cuidar muito bem de mim, mas...",
  str_homestory_chat_32221005 = "Ele nunca levou as coisas muito a sério. Na verdade, algumas pessoas até diriam que ele é preguiçoso.",
  str_homestory_chat_32221006 = "Fale sobre tirar cochilos o tempo todo.",
  str_homestory_chat_32221007 = "Mas suas habilidades eram de primeira linha, e nosso mestre o considerava um gênio.",
  str_homestory_chat_32221008 = "Quando penso nisso, ele provavelmente estava em um nível completamente diferente do nosso.",
  str_homestory_chat_32221009 = "Vou fazer uma leitura.",
  str_homestory_chat_32221010 = "Lendo, huh? Estou curioso para saber que tipo de livros você lê?",
  str_homestory_chat_32221011 = "Nos meus dias de templo, eu apenas lia todos os tipos de livros.",
  str_homestory_chat_32221012 = "Além dos estudos metafísicos, também lemos sobre artes marciais e todos os tipos de outras coisas.",
  str_homestory_chat_32221013 = "Embora naquela época eu estivesse um pouco mais interessado em treinamento de artes marciais do que em livros...",
  str_homestory_chat_32221014 = "Diga, que tal dar aos nossos amigos demônios uma rápida lição de literatura?",
  str_homestory_chat_32221015 = "Afinal, apenas saber como lutar nunca é suficiente.",
  str_homestory_chat_32221016 = "Tudo bem, vou falar com Ah Ding e os outros. Até mais tarde!",
  str_homestory_chat_32221017 = "Claro, te vejo daqui a pouco.",
  str_homestory_chat_32222001 = "Talvez vá terminar algum trabalho.",
  str_homestory_chat_32222002 = "Trabalho, hein? Sim, eu também.",
  str_homestory_chat_32222003 = "Eu acabei de aceitar um novo emprego hoje.",
  str_homestory_chat_32222004 = "Aparentemente, algo tem causado um alvoroço em uma casa antiga, mas eles não sabem se é um Eclipsite ou um animal selvagem.",
  str_homestory_chat_32222005 = "Não faz diferença, realmente. Eu vou arrastar o que quer que esteja lá e dar uma boa surra de qualquer maneira.",
  str_homestory_chat_32222006 = "Espero que nada dê errado...",
  str_homestory_chat_32222007 = "Não se preocupe, Ah Ding e os outros estarão comigo.",
  str_homestory_chat_32222008 = "Se algo der errado, sempre posso contar com a técnica de cabeçada de ferro do Ah Ding.",
  str_homestory_chat_32222009 = "Boa sorte!",
  str_homestory_chat_32222010 = "Bem, eu deveria começar a me preparar para sair.",
  str_homestory_chat_32223001 = "Pode ser que eu vá visitar um amigo.",
  str_homestory_chat_32223002 = "Visitando um amigo? Isso é sempre bom.",
  str_homestory_chat_32223003 = "Estive viajando por Longzhou por anos e fiz muitos amigos nesse meio tempo.",
  str_homestory_chat_32223004 = "Falando nisso, você já fez amizade com pessoas que não têm nada em comum com você?",
  str_homestory_chat_32223005 = "Isso.",
  str_homestory_chat_32223006 = "Eu tinha a sensação de que você diria isso.",
  str_homestory_chat_32223007 = "Afinal, este Colosso é lar de muitas pessoas com ascendência de demônios.",
  str_homestory_chat_32223008 = "O mundo é vasto, e as visões das pessoas devem ser igualmente amplas.",
  str_homestory_chat_32223009 = "Não muito.",
  str_homestory_chat_32223010 = "Sério...? Suponho que isso também seja compreensível.",
  str_homestory_chat_32223011 = "Afinal, o mundo está cheio de problemas que nasceram de pessoas se entendendo mal.",
  str_homestory_chat_32223012 = "Mas acho que as pessoas vão se tornar mais sábias algum dia...",
  str_homestory_chat_32223013 = "Sábio o suficiente para aceitar as coisas que não entendem.",
  str_homestory_chat_32223014 = "Espero que sim.",
  str_homestory_chat_32224001 = "Eu estava prestes a fazer algum exercício.",
  str_homestory_chat_32224002 = "Exercício, hein? De repente, não me sinto mais cansado!",
  str_homestory_chat_32224003 = "O treinamento é como construir um castelo de areia: tudo desmorona se você parar por um dia sequer.",
  str_homestory_chat_32224004 = "Então, o que você acha? Posso me juntar a você hoje?",
  str_homestory_chat_32224005 = "Você tem uma boa base, e o treinamento certamente trará à tona seu incrível potencial.",
  str_homestory_chat_32224006 = "N-Não importa...",
  str_homestory_chat_32224007 = "Sério? Que droga.",
  str_homestory_chat_32224008 = "Talvez eu vá apenas treinar com os fiendlings.",
  str_homestory_chat_32224009 = "Claro. Você deve ser capaz de levantar Ah Ding sem problemas!",
  str_homestory_chat_32224010 = "Por outro lado, os demônios elefantes do Reino Dian...",
  str_homestory_chat_32224011 = "Eu nem tentaria levantar um daqueles!",
  str_homestory_chat_146901001 = "Pierre",
  str_homestory_chat_124901001 = "Kuro",
  str_homestory_chat_151901001 = "Sork",
  str_homestory_chat_173901001 = "Patsy",
  str_homestory_chat_104901001 = "Kuma",
  str_homestory_chat_115901001 = "Hachi",
  str_homestory_chat_247901001 = "Momo",
  str_homestory_chat_32399999 = "Se você pudesse ser um animal, qual seria?",
  str_homestory_chat_32321001 = "Raposa da neve.",
  str_homestory_chat_32321002 = "Eu entendo você! Raposas da neve são legais!",
  str_homestory_chat_32321003 = "Ágeis, móveis, caçadores excepcionais com a habilidade de se misturar à neve para se ocultar!",
  str_homestory_chat_32321004 = "Incrivelmente alta sobrevivência! Ótima escolha.",
  str_homestory_chat_32321005 = "Na verdade, eu escolhi isso apenas porque...",
  str_homestory_chat_32321006 = "Raposas da neve são fofas.",
  str_homestory_chat_32321007 = "Eles são adoravelmente fofos.",
  str_homestory_chat_32321008 = "Se todo caçador fosse tão mortal quanto você...",
  str_homestory_chat_32321009 = "Seria melhor se eu me tornasse um animalzinho fofo e os conquistasse com minha fofura!",
  str_homestory_chat_32321010 = "Você ama raposas da neve, não é?",
  str_homestory_chat_32321011 = "Se eu fosse um, talvez viveria o resto da minha vida em paz sob sua proteção.",
  str_homestory_chat_32321012 = "Que suposição lógica e razoável!",
  str_homestory_chat_32321013 = "É exatamente assim que um auroriano pensa!",
  str_homestory_chat_32321014 = "Mas os animais na neve não se importam em agradar os Aurorianos.",
  str_homestory_chat_32321015 = "Ahem... Desculpe, eu não sou nem um animal nem um auroriano.",
  str_homestory_chat_32321016 = "Eu sou apenas um pequeno celestita fraco que coloca a sobrevivência acima de tudo.",
  str_homestory_chat_32322001 = "Urso Grizzly.",
  str_homestory_chat_32322002 = "...",
  str_homestory_chat_32322003 = "PlayerName...",
  str_homestory_chat_32322004 = "O que está errado? Por que a pena em seus olhos?",
  str_homestory_chat_32322005 = "O que? Não, não tenho pena. Eu entendo.",
  str_homestory_chat_32322006 = "Você é um bobo sem muita força física, então...",
  str_homestory_chat_32322007 = "Naturalmente, você deseja um corpo poderoso como o de um urso grizzly.",
  str_homestory_chat_32322008 = "Eu entendo. Eu realmente entendo!",
  str_homestory_chat_32322009 = "O que você tá dizendo?",
  str_homestory_chat_32322010 = "\"Um fracote sem muita força física\"? Isso é um pouco demais!",
  str_homestory_chat_32322011 = "Eu só pensei—",
  str_homestory_chat_32322012 = "Só pensou o quê?",
  str_homestory_chat_32322013 = "A maneira como um urso pardo dorme durante todo o inverno é o que eu gostaria de fazer!",
  str_homestory_chat_32322014 = "PlayerName...",
  str_homestory_chat_32322015 = "Por que há mais pena em seus olhos agora?",
  str_homestory_chat_32323001 = "Gaivota.",
  str_homestory_chat_32323002 = "Ah, você quer dizer aqueles pássaros obcecados por batatas fritas?",
  str_homestory_chat_32323003 = "Espera, não...",
  str_homestory_chat_32323004 = "Batatas fritas não são a única coisa que eles comem.",
  str_homestory_chat_32323005 = "Na verdade, eles não são nada exigentes quando se trata de comida.",
  str_homestory_chat_32323006 = "Frutas silvestres, algas, peixes, insetos... Eles comem tudo isso - e batatas fritas também, é claro.",
  str_homestory_chat_32323007 = "Eles são muito de mente aberta e vão tentar qualquer coisa.",
  str_homestory_chat_32323008 = "Isso é muito próximo de como eu quero viver!",
  str_homestory_chat_32323009 = "Agora que você diz isso, você mencionou antes...",
  str_homestory_chat_32323010 = "Você quer visitar todos os cantos do mundo e ver tudo.",
  str_homestory_chat_32323011 = "Esse é o pássaro perfeito para você!",
  str_homestory_chat_32323012 = "Você é um Celestita e eles são conhecidos por estarem associados ao céu e ao voo.",
  str_homestory_chat_32323013 = "A Colossus é as minhas asas.",
  str_homestory_chat_32323014 = "Você está convidado a viajar comigo se quiser!",
  str_homestory_chat_32323015 = "Enquanto não comermos batatas fritas o tempo todo.",
  str_homestory_chat_32323016 = "Pare de falar sobre batatas fritas!",
  str_homestory_chat_32324001 = "Coelho.",
  str_homestory_chat_32324002 = "Sério? Essa é uma escolha única.",
  str_homestory_chat_32324003 = "Os coelhos não conseguem lutar e estão no final da cadeia alimentar na natureza.",
  str_homestory_chat_32324004 = "Por que você iria querer ser um animal tão fraco?",
  str_homestory_chat_32324005 = "Coelhos não são fracos.",
  str_homestory_chat_32324006 = "Ninguém cuida dos coelhos.",
  str_homestory_chat_32324007 = "A aparência tímida e inofensiva é na verdade a sua melhor arma.",
  str_homestory_chat_32324008 = "Por que mais Novio escolheria um coelho como seu parceiro de inteligência?",
  str_homestory_chat_32324009 = "Em comparação com ataques preventivos, prefiro ataques reativos.",
  str_homestory_chat_32324010 = "Os coelhos têm audição aguçada.",
  str_homestory_chat_32324011 = "Eles se escondem no escuro e ouvem tudo ao redor deles.",
  str_homestory_chat_32324012 = "Tudo o que eles sentem ajuda seus amigos.",
  str_homestory_chat_32324013 = "Você não acha que isso soa muito como um celestita com habilidades psíquicas?",
  str_homestory_chat_32324014 = "Verdade. Sua perspectiva de celestita é muito diferente de um auroriano.",
  str_homestory_chat_32324015 = "Além disso, isso me deu uma nova perspectiva para melhorar minha caça.",
  str_homestory_chat_32324016 = "Oh não, eu não acabei de vender os coelhos pela água abaixo, vendi?",
  str_homestory_chat_32324017 = "Você verá isso na hora do jantar!",
  str_homestory_chat_32325001 = "Baleia.",
  str_homestory_chat_32325002 = "Senhor do mar! Uma escolha muito razoável.",
  str_homestory_chat_32325003 = "Isso é porque os Celestitas desejam poder?",
  str_homestory_chat_32325004 = "Não exatamente.",
  str_homestory_chat_32325005 = "Existe uma espécie de baleia chamada orca. Ouvi dizer que eles valorizam muito a família.",
  str_homestory_chat_32325006 = "Eles viveriam com sua família até a morte.",
  str_homestory_chat_32325007 = "Acho que isso é algo que eu aprecio e me atrai.",
  str_homestory_chat_32325008 = "PlayerName...",
  str_homestory_chat_32325009 = "Desculpe, eu não queria lembrá-lo do seu passado.",
  str_homestory_chat_32325010 = "Tudo bem, sem preocupações.",
  str_homestory_chat_32325011 = "Tenho uma família no Colossus.",
  str_homestory_chat_32325012 = "Então, meu desejo já se tornou realidade.",
  str_homestory_chat_32325013 = "Soroz é minha família.",
  str_homestory_chat_32325014 = "Faremos qualquer coisa pelo outro.",
  str_homestory_chat_32325015 = "Ah, agora eu entendi.",
  str_homestory_chat_32325016 = "Eu sou apenas como você.",
  str_homestory_chat_32325017 = "Perdi minha família há muito tempo, mas encontrei uma nova família.",
  str_homestory_chat_32325018 = "Nesse sentido, família vai além de apenas um vínculo de sangue.",
  str_homestory_chat_32325019 = "Eu sabia que você conseguiria.",
  str_homestory_chat_32325020 = "Obrigado, Tiare.",
  str_homestory_chat_32499999 = "Ribbit!",
  str_homestory_chat_32421001 = "Vejo que o pequeno companheiro também gosta daqui!",
  str_homestory_chat_32599999 = "Se você tivesse que escolher um hobby de colecionar, qual você escolheria?",
  str_homestory_chat_32521001 = "Estatuetas.",
  str_homestory_chat_32521002 = "Como os usados em mesas de areia para determinar táticas de combate?",
  str_homestory_chat_32521003 = "Não fazia ideia de que você era tão entusiasta do militarismo.",
