  str_homestory_chat_32521005 = "Todos me chamam de Navegador, o que também me faz um tipo de comandante.",
  str_homestory_chat_32521006 = "Além disso, não há nada de errado em praticar estratégias de combate de vez em quando.",
  str_homestory_chat_32521007 = "PlayerName... Eu não percebi que você se preparava tão minuciosamente para cada batalha.",
  str_homestory_chat_32521008 = "Estou te vendo sob uma nova luz novamente.",
  str_homestory_chat_32521009 = "Acho que você está com a ideia errada...",
  str_homestory_chat_32521010 = "Quando digo estatuetas, me refiro às coloridas e caras—",
