  str_homestory_chat_32522003 = "Então é isso que você gosta.",
  str_homestory_chat_32522004 = "Sim! A mobília não apenas torna nossas vidas mais confortáveis...",
  str_homestory_chat_32522005 = "Isso também me ajuda a me aproximar dos meus amigos.",
  str_homestory_chat_32522006 = "Sim, eu vi você e seus amigos tendo conversas apaixonadas ao redor de seus móveis.",
  str_homestory_chat_32522007 = "Entendi agora. Você usa móveis como uma espécie de \"armadilha para amigos\".",
  str_homestory_chat_32522008 = "Depois de arrumar o móvel certo, você espera pela oportunidade perfeita—",
  str_homestory_chat_32522009 = "Para criar memórias inesquecíveis de nossas aventuras.",
