  str_homestory_chat_32522013 = "E-E-E-Espere um segundo!",
  str_homestory_chat_32522014 = "Algo sobre isso não parece certo!",
  str_homestory_chat_32523001 = "Vício.",
  str_homestory_chat_32523002 = "Você coletaria... Tenente Vice? Desculpe, mas eu não entendi.",
  str_homestory_chat_32523003 = "Afinal, ela é uma pessoa extremamente única.",
  str_homestory_chat_32523004 = "Quer dizer que você não entende? Na verdade, existem toneladas de diferentes Vícios!",
  str_homestory_chat_32523005 = "Como \"Grita comigo para limpar o armazém\" Vice, e \"Me incomoda para assumir mais trabalhos\" Vice...",
  str_homestory_chat_32523006 = "\"Me lembra de limpar meu quarto\" Vice, e \"Me força a comer comida horrivelmente indescritível\" Vice...",
  str_homestory_chat_32523007 = "... Mesmo que todos esses pontos soem incrivelmente negativos, acho que agora entendi.",
  str_homestory_chat_32523008 = "Você só quer ver todos os lados do Tenente Vice, não é?",
  str_homestory_chat_32523009 = "Arram, eu não disse isso!",
  str_homestory_chat_32524001 = "Colossos.",
  str_homestory_chat_32524002 = "Colossi... Você realmente pode coletar esses?",
  str_homestory_chat_32524003 = "Bem, obviamente eu não os colocaria em uma prateleira ou algo assim. Eu acho...",
  str_homestory_chat_32524004 = "O que eu realmente quero é ver ainda mais Colossi por aí.",
  str_homestory_chat_32524005 = "PlayerName... Pelo que eu posso ver, você deve realmente sentir falta de sua casa.",
  str_homestory_chat_32524006 = "Você tem razão.",
  str_homestory_chat_32524007 = "Acho que posso me relacionar.",
  str_homestory_chat_32524008 = "Quando eu estava lutando para restaurar a honra da minha família...",
  str_homestory_chat_32524009 = "Qualquer coisa que me lembrasse de casa fortaleceria meu espírito de luta cem vezes mais.",
  str_homestory_chat_32524010 = "Não é bem isso.",
  str_homestory_chat_32524011 = "Os Colossos têm muito a me ensinar sobre eles mesmos, assim como os Celestitas.",
  str_homestory_chat_32524012 = "Com esse conhecimento, posso estar preparado para quaisquer problemas que Soroz possa ter no futuro!",
  str_homestory_chat_32524013 = "Então, em vez de se apegar ao passado, você luta para preservar o que valoriza no presente...",
  str_homestory_chat_32524014 = "Você realmente é determinado, Celestita.",
  str_homestory_chat_32524015 = "Obrigado por entender, Rachel.",
  str_homestory_chat_32524016 = "Aos meus olhos, você faz parte da minha família há muito tempo.",
  str_homestory_chat_32525001 = "Aurorianos.",
  str_homestory_chat_32525002 = "É isso que os Aurorians significam para você? Colecionáveis?",
  str_homestory_chat_32525003 = "Bem, sim! Afinal, sou um perfeccionista de coração!",
  str_homestory_chat_32525004 = "E o que exatamente isso significa?",
  str_homestory_chat_32525005 = "Não entenda mal. É apenas uma metáfora.",
  str_homestory_chat_32525006 = "Eu só quero lutar ao lado de tantos Aurorianos quanto possível.",
  str_homestory_chat_32525007 = "Dessa forma, posso continuar desenvolvendo minha coleção... Quero dizer, minha capacidade de adaptação...",
  str_homestory_chat_32525008 = "E então nenhum problema será muito difícil para eu lidar! Faz sentido, certo?",
  str_homestory_chat_32525009 = "Entendo... Desculpe por ter duvidado de você agora mesmo.",
