  str_homestory_chat_32525011 = "Por que não fazemos uma batalha de prática na próxima vez?",
  str_homestory_chat_32525012 = "Hã?",
  str_homestory_chat_32699999 = "Bem, se não é o Último Celestita! O que você está ocupado?",
  str_homestory_chat_32621001 = "Hum...",
  str_homestory_chat_32621002 = "Eu estava prestes a ir fazer algum exercício.",
  str_homestory_chat_32621003 = "Entendi! Um pouco de treino de força, huh?",
