  str_homestory_chat_32621007 = "Por exemplo, você já viu um leão treinar a si mesmo antes?",
  str_homestory_chat_32621008 = "Claro que não! Isso porque é completamente inaceitável para uma criatura naturalmente poderosa treinar para se tornar ainda mais poderosa!",
  str_homestory_chat_32621009 = "Eu estava planejando fazer uma pausa.",
  str_homestory_chat_32621010 = "Eu vejo. Descansando um pouco antes da próxima batalha brutal, hein?",
