  str_homestory_chat_32623008 = "De alguma forma, seu juramento só me faz preocupar ainda mais...",
  str_homestory_chat_32624001 = "Meio que quero um lanche agora.",
  str_homestory_chat_32624002 = "Um lanche? Então você encontrou a pessoa certa!",
  str_homestory_chat_32624003 = "Eu tenho todos os tipos de doces. Aqui, escolha o seu!",
  str_homestory_chat_32624004 = "Mas eu quero algo salgado.",
  str_homestory_chat_32624005 = "Eu também tenho doces salgados! Como este, um pirulito de pimenta fantasma!",
  str_homestory_chat_32624006 = "É feito com pimentas fantasma reais. Dizem que você não conseguirá respirar após apenas algumas lambidas!",
  str_homestory_chat_32624007 = "Mas eu ainda não tentei por mim mesmo, então não sei se é verdade ou não.",
  str_homestory_chat_32624008 = "Então, por que você me daria isso?",
  str_homestory_chat_32624009 = "Não se importe se eu fizer isso!",
  str_homestory_chat_32624010 = "Fique à vontade para pegar o que quiser. Mas já vou avisando: tem algumas bombas misturadas aí, então tenha cuidado ao comê-las.",
  str_homestory_chat_32624011 = "B-Bombas? Quais são as bombas?",
  str_homestory_chat_32624012 = "Quer dizer que você não consegue distinguir um do outro? É totalmente óbvio!",
  str_homestory_chat_32624013 = "Talvez para você, mas eu não consigo distingui-los de forma alguma.",
  str_homestory_chat_32624014 = "Ah, você não tem jeito. Aqui, vou escolher um especialmente para você então.",
  str_homestory_chat_32624015 = "Tenho algumas outras coisas para fazer, então te vejo mais tarde.",
  str_homestory_chat_32799999 = "Algum jogo que você gostaria de jogar ultimamente?",
  str_homestory_chat_32721001 = "Jogos de role-playing",
  str_homestory_chat_32721002 = "Ah, boa escolha!",
  str_homestory_chat_32721003 = "O que te fez escolher isso?",
  str_homestory_chat_32721004 = "Você está mais interessado na configuração do jogo ou na história?",
  str_homestory_chat_32721005 = "O cenário",
  str_homestory_chat_32721006 = "É legal sentir como se estivesse vivendo em outro lugar.",
  str_homestory_chat_32721007 = "O tipo de experiência... Eu entendi.",
  str_homestory_chat_32721008 = "A história",
  str_homestory_chat_32721009 = "É tipicamente coisas do tipo bons-rapazes-matando-o-dragão.",
  str_homestory_chat_32721010 = "Mas eu não me importo com isso.",
  str_homestory_chat_32721011 = "O tipo que faz bem... Eu posso curtir isso.",
  str_homestory_chat_32721012 = "Você não gosta desse tipo de jogo, Batia?",
  str_homestory_chat_32721013 = "Eu tenho, é só que... Eu não tenho uma preferência particular.",
  str_homestory_chat_32721014 = "Eu aprecio mais quando há uma grande variedade para escolher.",
  str_homestory_chat_32722001 = "Jogos de estratégia",
  str_homestory_chat_32722002 = "Isso não é surpreendente!",
  str_homestory_chat_32722003 = "Gostaria de melhorar minha habilidade de navegação como um Celestita.",
  str_homestory_chat_32722004 = "Então, estou melhor composto ao enfrentar Eclipsitas.",
  str_homestory_chat_32722005 = "Então está dizendo...",
  str_homestory_chat_32722006 = "Você quer melhorar como contra-ataca através de jogos estratégicos?",
  str_homestory_chat_32722007 = "É impressionante que você pensaria nisso mesmo quando está jogando um jogo.",
  str_homestory_chat_32722008 = "Bem, na verdade eu venho treinando para isso.",
  str_homestory_chat_32722009 = "Seria bom jogar todos os tipos de simulações e cenários em um jogo.",
  str_homestory_chat_32723001 = "Jogos casuais",
  str_homestory_chat_32723002 = "Jogos de combinar peças são bem fáceis, certo?",
  str_homestory_chat_32723003 = "Uh, não necessariamente.",
  str_homestory_chat_32723004 = "Até esse tipo de jogo pode ser difícil e muito desafiador.",
  str_homestory_chat_32723005 = "Quão duro?",
  str_homestory_chat_32723006 = "Você não pode fazer um movimento sequer.",
  str_homestory_chat_32723007 = "Quão desafiador?",
  str_homestory_chat_32723008 = "Muitos requisitos estranhos que exigem tempo e esforço.",
  str_homestory_chat_32723009 = "Talvez eu deva reconsiderar.",
  str_homestory_chat_32724001 = "Tetrablox! Tetrablox!",
  str_homestory_chat_32724002 = "Você também gosta de Tetrablox?!",
  str_homestory_chat_32724003 = "Você poderia dizer isso, mas definitivamente não sou tão bom quanto você.",
  str_homestory_chat_32724004 = "Não sou rápido o suficiente para limpar tantos blocos.",
  str_homestory_chat_32724005 = "É parte sorte e parte habilidade... Eu posso te mostrar.",
  str_homestory_chat_32724006 = "Por que não miramos em alcançar o Nv.30 por agora?",
  str_homestory_chat_32725001 = "Na verdade, não",
  str_homestory_chat_32725002 = "Devemos ir lá fora.",
  str_homestory_chat_32725003 = "Fora? Você quer dizer fora-fora ou aqui-fora?",
  str_homestory_chat_32725004 = "Fora-fora",
  str_homestory_chat_32725005 = "Uh, eu não faço viagens com frequência...",
  str_homestory_chat_32725006 = "Tudo bem. Nós temos a Colossus.",
  str_homestory_chat_32725007 = "Aqui-fora",
  str_homestory_chat_32725008 = "Está tudo bem. É confortável aqui e temos um guarda-chuva.",
  str_homestory_chat_32725009 = "Não estou sendo um incômodo para você, estou?",
  str_homestory_chat_32725010 = "Se cairmos...",
  str_homestory_chat_32725011 = "Podemos olhar para o céu deitados de costas!",
  str_homestory_chat_32899999 = "Se você pudesse colocar as mãos em um item mágico, o que você gostaria?",
  str_homestory_chat_32821001 = "Uma impressora de dinheiro.",
  str_homestory_chat_32821002 = "Caramba! Isso é certamente... um tipo particular de \"mágica\", eu acho.",
  str_homestory_chat_32821003 = "Estou brincando... mas estamos seriamente com pouco dinheiro para a manutenção do Colosso nos dias de hoje.",
  str_homestory_chat_32821004 = "Já estou equilibrando oito trabalhos por dia!",
  str_homestory_chat_32821005 = "Se esse é o caso, por que não trabalhar para a Verdadeira Ordem?",
  str_homestory_chat_32821006 = "O pagamento que ofereço não desonrará a reputação de Varaki.",
  str_homestory_chat_32821007 = "Para onde devo enviar meu currículo?!",
  str_homestory_chat_32821008 = "Não há necessidade de tais formalidades mundanas. Quando a chance liderada pela Verdade chegar, trabalharemos juntos naturalmente.",
  str_homestory_chat_32821009 = "Forçar isso não trará nenhum bem.",
  str_homestory_chat_32821010 = "Isso parece meio instável...",
  str_homestory_chat_32821011 = "Você não está apenas fazendo promessas vazias, está?",
  str_homestory_chat_32821012 = "Honestamente, estou surpreso que você pense assim.",
  str_homestory_chat_32821013 = "Você realmente nos vê na Verdadeira Ordem como um grupo suspeito que engana seus seguidores?",
  str_homestory_chat_32821014 = "Absolutamente não! É só que eu tenho encontrado muitos chefes duvidosos ultimamente...",
  str_homestory_chat_32822001 = "Uma capa de invisibilidade.",
  str_homestory_chat_32822002 = "Ai...?",
  str_homestory_chat_32822003 = "Por que... está me dando esse olhar?",
  str_homestory_chat_32822004 = "He...",
  str_homestory_chat_32822005 = "Qual a graça nisso?!",
  str_homestory_chat_32822006 = "Não precisa se envergonhar, Navegador. É natural ter esses pensamentos na sua idade.",
  str_homestory_chat_32822007 = "Sobre quais pensamentos você está falando? Eu só acho que uma capa de invisibilidade seria ótima para missões furtivas!",
  str_homestory_chat_32822008 = "Sim, claro. Você não iria querer de outra forma.",
  str_homestory_chat_32822009 = "Por que diabos você acha que eu quero isso?",
  str_homestory_chat_32823001 = "Uma vassoura que varre sozinha.",
  str_homestory_chat_32823002 = "Oh céus, com todos os itens mágicos para escolher, você só quer uma vassoura? Seus desejos são bastante modestos.",
  str_homestory_chat_32823003 = "Se você não quer fazer a limpeza, por que não contrata um servo?",
  str_homestory_chat_32823004 = "Alguém tão alto quanto você pode não entender...",
  str_homestory_chat_32823005 = "Mas comandar alguém, mesmo que eu esteja pagando, me faz sentir desconfortável.",
  str_homestory_chat_32823006 = "Mas se for uma vassoura mágica, posso dar ordens sem me sentir mal!",
  str_homestory_chat_32823007 = "Eu vejo. Você é realmente uma alma bondosa.",
  str_homestory_chat_32823008 = "Mas, se você suprimir seu \"eu\" demais pelos outros, pode se desviar da Verdade.",
  str_homestory_chat_32823009 = "Cuidar dos outros é parte do \"eu\".",
  str_homestory_chat_32823010 = "Bem argumentado. Sua sabedoria e perspicácia são realmente extraordinárias.",
  str_homestory_chat_32823011 = "De fato, se você pudesse expressar completamente sua natureza gentil...",
  str_homestory_chat_32823012 = "Você certamente se tornaria um santo autossacrificante, assim como Nails...",
  str_homestory_chat_32823013 = "N-n-não, isso não é necessário. Estou bem sendo apenas comum!",
  str_homestory_chat_32823014 = "Então, só os egomaníacos conseguem se aproximar da Verdade?",
  str_homestory_chat_32823015 = "Heh... Suas palavras são bem afiadas; que adorável.",
  str_homestory_chat_32823016 = "Mas sim, como se verifica, aqueles que compreendem a Verdade tendem a ser egomaníacos.",
  str_homestory_chat_32823017 = "Suas palavras afiadas são como os espinhos de uma rosa... Talvez seja a Verdade se manifestando em você... quem sabe.",
  str_homestory_chat_32823018 = "Esse Senhor da Verdade não é um pouco difícil de lidar...?",
  str_homestory_chat_32824001 = "Uma ampulheta que retrocede o tempo.",
  str_homestory_chat_32824002 = "Retrocedendo no tempo? Uma escolha clássica.",
  str_homestory_chat_32824003 = "Desculpe-me por perguntar, mas é porque você quer voltar dezessete anos para mudar o que aconteceu em Eraveil?",
  str_homestory_chat_32824004 = "De nada.",
  str_homestory_chat_32824005 = "É natural que você queira isso.",
  str_homestory_chat_32824006 = "Se você realmente tiver a chance de fazer isso acontecer, talvez... Eu estarei ao seu lado.",
  str_homestory_chat_32824007 = "O quê? Eu imaginei que todos seriam contra uma mudança tão grande na história...",
  str_homestory_chat_32824008 = "Tenho medo de mudar as coisas tanto assim.",
  str_homestory_chat_32824009 = "Todo o Astra seria impactado...",
  str_homestory_chat_32824010 = "No máximo, eu apenas voltaria para o dia antes de ontem e encontraria meu dinheiro perdido... haha.",
  str_homestory_chat_32824011 = "...O tecido do tempo é extremamente misterioso.",
  str_homestory_chat_32824012 = "A maneira como o \"passado\" é formado é muito mais complexa do que pensamos.",
  str_homestory_chat_32824013 = "Às vezes, pode ser o \"futuro\" que molda o \"passado\".",
  str_homestory_chat_32824014 = "...",
  str_homestory_chat_32825001 = "Uma poção que permite que você aprenda enquanto dorme.",
  str_homestory_chat_32825002 = "...",
  str_homestory_chat_32825003 = "Dos seus olhos, eu vejo uma profunda desaprovação...",
  str_homestory_chat_32825004 = "Heh... Eu aprecio o quão inteligente você é.",
  str_homestory_chat_32825005 = "Existem toneladas de romances de fantasia centrados em torno da magia...",
  str_homestory_chat_32825006 = "Mas mesmo eles raramente descrevem a poção que você quer. Você sabe por quê?",
  str_homestory_chat_32825007 = "Os autores não são ousados o suficiente?",
  str_homestory_chat_32825008 = "Porque o conhecimento é o único caminho para a Verdade.",
  str_homestory_chat_32825009 = "E o aprendizado é uma coisa que não permite atalhos.",
  str_homestory_chat_32825010 = "Você entendeu agora?",
  str_homestory_chat_32825011 = "...Eu entendo totalmente, Professora Victoria!",
  str_homestory_chat_32999999 = "Você já se arrependeu de alguma coisa?",
  str_homestory_chat_32921001 = "Fiquei acordado por três dias jogando.",
  str_homestory_chat_32921002 = "Jogos...? O que são esses?",
  str_homestory_chat_32921003 = "Eles são demônios.",
  str_homestory_chat_32921004 = "Demônios? Você quer dizer criaturas vis como os Eclipsitas ou os Necroservos?",
  str_homestory_chat_32921005 = "Eu vou proteger você, PlayerName, porque é exatamente por isso que o Senhor me concedeu o poder do Sangue Sagrado.",
  str_homestory_chat_32921006 = "O Sangue Sagrado não pode fazer nada sobre isso.",
  str_homestory_chat_32921007 = "Diabos chamados jogos usam a alegria como isca, desperdiçando minha juventude e drenando meu dinheiro...",
  str_homestory_chat_32921008 = "Mesmo o guerreiro mais forte não pode escapar de suas garras!",
  str_homestory_chat_32921009 = "Mas... Mas parece que você está simplesmente cedendo à tentação sem oferecer resistência.",
  str_homestory_chat_32921010 = "Você deve me proteger.",
  str_homestory_chat_32921011 = "Na próxima vez que Gronru me tentar com jogos, você tem que bloqueá-la!",
  str_homestory_chat_32921012 = "Gronru?",
  str_homestory_chat_32921013 = "Ela é a rainha demônio dos jogos no inferno. Se não fosse por ela, eu não teria acabado assim...",
  str_homestory_chat_32921014 = "Não é apenas... culpando outra pessoa pelo seu erro?",
  str_homestory_chat_32921015 = "Talvez isso seja pelo que você realmente deveria estar se arrependendo, não acha?",
  str_homestory_chat_32921016 = "Argh...! Vamos esquecer esse assunto. Adeus!",
  str_homestory_chat_32922001 = "Empilhando uma torre de frutas em um restaurante.",
  str_homestory_chat_32922002 = "Uma torre de frutas?",
  str_homestory_chat_32922003 = "Ahem, você conhece aqueles restaurantes onde você pode pegar uma salada de frutas self-service se pedir um prato principal?",
  str_homestory_chat_32922004 = "Você pode pegar o quanto quiser, mas apenas uma vez.",
  str_homestory_chat_32922005 = "Portanto, empilhar o máximo de salada possível em um prato se torna uma forma de arte.",
  str_homestory_chat_32922006 = "Então, você empilhou uma... torre de frutas no seu prato?",
  str_homestory_chat_32922007 = "Não, não me olhe assim...",
  str_homestory_chat_32922008 = "Isso requer habilidade real!",
  str_homestory_chat_32922009 = "...Se você se orgulha, por que se arrependeu?",
  str_homestory_chat_32922010 = "Comi a torre inteira de frutas e tive diarreia por três dias...",
  str_homestory_chat_32922011 = "Então você recebeu o castigo do Senhor; seus pecados foram purificados, PlayerName.",
  str_homestory_chat_32922012 = "Seus olhos ficaram quentes novamente, o que me faz sentir ainda mais estranho...",
  str_homestory_chat_32923001 = "Acelerando.",
  str_homestory_chat_32923002 = "Acelerando... Eu não sabia que o Colossus tinha limites de velocidade.",
  str_homestory_chat_32923003 = "O céu agora é meu para vagar livremente...",
  str_homestory_chat_32923004 = "Mas nos dias em que muitos Colossos estavam no céu, havia limites de velocidade habituais.",
  str_homestory_chat_32923005 = "Eles deveriam manter outros Colossi e pássaros seguros, e eu os seguia na maior parte do tempo.",
  str_homestory_chat_32923006 = "Então por que você acelerou?",
  str_homestory_chat_32923007 = "Aniversário do Vice.",
  str_homestory_chat_32923008 = "Acelerei para Umbraton para pegar um dos cinquenta bolos de frutas ultra-luxuosos de edição limitada.",
  str_homestory_chat_32923009 = "Aniversário de Carleen.",
  str_homestory_chat_32923010 = "Acelerei para Lumópolis para o banquete de aniversário e tive que pegar meu vestido de noite na lavanderia no caminho...",
  str_homestory_chat_32923011 = "Entendo...",
  str_homestory_chat_32923012 = "Já que foi por ela, eu não posso te culpar.",
  str_homestory_chat_32923013 = "E você já se arrependeu sinceramente, certo?",
  str_homestory_chat_32923014 = "O-Claro!",
  str_homestory_chat_32923015 = "Mesmo sem ninguém impondo, você ainda adere aos costumes do seu clã e se arrepende quando os quebra.",
  str_homestory_chat_32923016 = "Seu caráter nobre é admirável.",
  str_homestory_chat_32923017 = "O Senhor da Verdade irá abençoar você, PlayerName.",
  str_homestory_chat_32923018 = "Obrigado... Quero dizer, agradeça a Ele!",
  str_homestory_chat_32924001 = "Falta perseverança.",
  str_homestory_chat_32924002 = "É difícil para você se ater às coisas?",
  str_homestory_chat_32924003 = "Sim... especialmente quando decido malhar, cof...",
  str_homestory_chat_32924004 = "Treinar o corpo é um processo doloroso. Eu passei por isso, então eu entendo.",
  str_homestory_chat_32924005 = "Na verdade, você não precisa se esforçar tanto porque sua força não está em seu corpo.",
  str_homestory_chat_32924006 = "O exercício não combina com você, mas deve haver algo com o qual você possa se comprometer, certo?",
  str_homestory_chat_32924007 = "Mais ou menos... Eu acho...",
  str_homestory_chat_32924008 = "Como qual?",
  str_homestory_chat_32924009 = "Comendo... dormindo...",
  str_homestory_chat_32924010 = "...",
  str_homestory_chat_32924011 = "Tem mais! Tipo...",
  str_homestory_chat_32924012 = "...Como respirar!",
  str_homestory_chat_32924013 = "...",
  str_homestory_chat_33099999 = "Que tipo de livros você gosta de ler?",
  str_homestory_chat_33021001 = "Romances.",
  str_homestory_chat_33021002 = "Interessante.",
  str_homestory_chat_33021003 = "Sabe de uma coisa? O que você chama de romances tem uma história surpreendentemente curta.",
  str_homestory_chat_33021004 = "Eles estavam apenas começando na minha época.",
  str_homestory_chat_33021005 = "Isso é novidade para mim!",
  str_homestory_chat_33021006 = "Pensei que romances... hum, sempre estiveram lá?",
  str_homestory_chat_33021007 = "É um viés cognitivo comum pensar que novos conceitos em cultura e sociedade sempre existiram.",
  str_homestory_chat_33021008 = "Não apenas romances, conceitos como infância, amor, razão e assim por diante também são produtos dos tempos modernos.",
  str_homestory_chat_33021009 = "Uma vez que você se acostuma com eles, é difícil imaginar a vida de qualquer outra maneira...",
  str_homestory_chat_33021010 = "Daí o equívoco de que \"eles sempre existiram.\"",
  str_homestory_chat_33021011 = "É meio difícil de acreditar.",
  str_homestory_chat_33021012 = "Os aurorianos não tinham histórias para ler no passado?",
  str_homestory_chat_33021013 = "Naquela época, tínhamos épicos, dramas e fábulas, que têm elementos de narrativa, mas são bastante diferentes de romances.",
  str_homestory_chat_33021014 = "Ultimamente, tenho lido alguns dos romances mais vendidos exibidos nas livrarias. Comparado a épicas e tal...",
  str_homestory_chat_33021015 = "Suas tramas são mais complexas, as emoções mais matizadas, sem dúvida um produto da prosperidade social.",
  str_homestory_chat_33021016 = "Há cem anos, os aurorianos não tinham tempo para ponderar sobre tais coisas \"inúteis\".",
  str_homestory_chat_33021017 = "Entendo... É realmente esclarecedor conversar com você!",
  str_homestory_chat_33022001 = "Livro de história.",
  str_homestory_chat_33022002 = "É raro alguém da sua idade se interessar por história.",
  str_homestory_chat_33022003 = "É bom ler história, mas tenha cuidado para não pensar que tudo escrito em um livro é absolutamente verdadeiro.",
  str_homestory_chat_33022004 = "Entendi, Sr. Wilhelm. Você quer dizer \"a história é escrita pelos vencedores\", certo?",
  str_homestory_chat_33022005 = "Essa afirmação apenas reflete a distorção deliberada da história por aqueles no poder. A realidade é muito mais complexa.",
  str_homestory_chat_33022006 = "Mesmo quando os historiadores escrevem a história com a nobre intenção de \"restaurar a verdade\"...",
  str_homestory_chat_33022007 = "Eles são inevitavelmente influenciados pelo espírito e ethos de seus próprios tempos.",
  str_homestory_chat_33022008 = "O que eles escrevem já é a \"história vista pelo contemporâneo\", não a \"história\" em si.",
  str_homestory_chat_33022009 = "Você está dizendo... a história não pode ser restaurada com precisão?",
  str_homestory_chat_33022010 = "Como esperado de um jovem que lê história, você já notou a ironia de \"história e verdade\".",
  str_homestory_chat_33023001 = "Poesia.",
  str_homestory_chat_33023002 = "Hmph, às vezes acho que você é muito maduro para sua idade, mas então você me surpreende com alguns interesses juvenis.",
  str_homestory_chat_33023003 = "Há um ditado que diz: \"Morrer jovem enquanto a juventude ainda persiste é uma bênção do poeta\". O que você acha disso?",
  str_homestory_chat_33023004 = "Concordo.",
  str_homestory_chat_33023005 = "Seus pensamentos são perigosos.",
  str_homestory_chat_33023006 = "Escrever poesia exige fervor juvenil. É melhor morrer cedo do que esperar essa paixão desaparecer.",
  str_homestory_chat_33023007 = "Uma vida sem paixão não vale a pena viver — é isso que você pensa?",
  str_homestory_chat_33023008 = "Definitivamente não, mas e aqueles poetas?",
  str_homestory_chat_33023009 = "Sempre há alguém que vê algo como o propósito de toda a sua vida, certo?",
  str_homestory_chat_33023010 = "Propósito de toda a vida... Para mim, talvez seja o caminho para me aproximar do Senhor.",
  str_homestory_chat_33023011 = "Você tem uma ótima percepção, PlayerName.",
  str_homestory_chat_33023012 = "Discordo.",
  str_homestory_chat_33023013 = "Você é contra a \"teoria do talento inato\"?",
  str_homestory_chat_33023014 = "Como assim?",
  str_homestory_chat_33023015 = "De todas as formas literárias, a poesia é a que mais exige talento.",
  str_homestory_chat_33023016 = "Muitos grandes poetas alcançam a fama em sua adolescência e vinte anos, esgotam seus talentos e depois se reduzem a mediocridade.",
  str_homestory_chat_33023017 = "Mas você não concorda com esse tipo de destino.",
  str_homestory_chat_33023018 = "Enquanto alguém vive, pode buscar a poesia concedida pelo divino com uma alma enriquecida por experiências mundanas.",
  str_homestory_chat_33023019 = "É isso que você acha?",
  str_homestory_chat_33023020 = "Eu... talvez. Eu odeio a ideia de limitar as possibilidades da vida à \"juventude\".",
  str_homestory_chat_33023021 = "Pensando bem, foi exatamente isso que você quis dizer.",
  str_homestory_chat_33023022 = "Mas eu nunca poderia expressar tão bem quanto você! Você é incrível, Sr. Wilhelm!",
  str_homestory_chat_33024001 = "Livros de ciência popular.",
  str_homestory_chat_33024002 = "Ciência, hein... Sem dúvida, fez grandes contribuições para a sociedade.",
  str_homestory_chat_33024003 = "Mas com o atual quadro científico, os Aurorians certamente estão se afastando da Verdade.",
  str_homestory_chat_33024004 = "Eh, como assim?",
  str_homestory_chat_33024005 = "Victoria já disse a você, \"A Verdade tem muitas dimensões\"?",
  str_homestory_chat_33024006 = "Ela diz isso muito!",
  str_homestory_chat_33024007 = "É aqui que o mistério reside.",
  str_homestory_chat_33024008 = "A ciência é construída sobre a previsibilidade.",
  str_homestory_chat_33024009 = "Fazer algo dez mil vezes e obter o mesmo resultado a cada vez é o que torna isso uma \"conclusão científica.\"",
  str_homestory_chat_33024010 = "Mas a Verdade reside na fagulha um-em-um-milhão.",
  str_homestory_chat_33024011 = "Você percebe em um único olhar, e esse olhar, não importa quantas vezes você o faça, é sempre diferente.",
  str_homestory_chat_33024012 = "Entendeu?",
  str_homestory_chat_33024013 = "Entendo.",
  str_homestory_chat_33024014 = "Bobagem. Se você realmente pode entender a partir das minhas palavras descuidadas, para que precisamos da Verdadeira Ordem?",
  str_homestory_chat_33024015 = "...",
  str_homestory_chat_33024016 = "Não entendi.",
  str_homestory_chat_33024017 = "Está bem. Você gosta de ciência, então continue estudando.",
  str_homestory_chat_33024018 = "Quando a ciência atinge seu ápice, pode se tornar outra porta de entrada para a Verdade.",
  str_homestory_chat_33025001 = "Textos teológicos.",
  str_homestory_chat_33025002 = "???",
  str_homestory_chat_33025003 = "...Ah, entendi.",
  str_homestory_chat_33025004 = "Você tem lido... como é chamado? \"Romances de fantasia\"? Aqueles baseados em mitos.",
  str_homestory_chat_33025005 = "E é por isso que você está intrigado pelos conceitos e cenários neles, certo?",
  str_homestory_chat_33025006 = "Huh? Não, Sr. Wilhelm.",
  str_homestory_chat_33025007 = "Ouvindo você mencionar muito \"a Verdade\" e \"Senhor\", eu quero entender do que você está falando.",
  str_homestory_chat_33025008 = "?!",
  str_homestory_chat_33025009 = "Por... mim?",
  str_homestory_chat_33025010 = "Sim. Acho suas conversas intrigantes e quero poder responder a você às vezes.",
  str_homestory_chat_33025011 = "...Ugh, é muito leviano ler textos teológicos com essa mentalidade?",
  str_homestory_chat_33025012 = "...Não, não é.",
  str_homestory_chat_33025013 = "O que foi?",
  str_homestory_chat_33025014 = "Nada! Vá ler agora.",
  str_homestory_chat_33025015 = "Se há algo que você não entende... sinta-se à vontade para me perguntar.",
  str_homestory_chat_33199999 = "Algum sonho interessante ultimamente?",
  str_homestory_chat_33121001 = "Sonhos interessantes?",
  str_homestory_chat_33121002 = "Não consigo pensar em nenhum...",
  str_homestory_chat_33121003 = "Hmm... Você está sob muita pressão?",
  str_homestory_chat_33121004 = "Não é cansativo dormir sem ter bons sonhos?",
  str_homestory_chat_33121005 = "Huh? Eu não diria isso...",
  str_homestory_chat_33121006 = "Muito do estresse se vai após uma boa noite de sono.",
  str_homestory_chat_33121007 = "É assim? Mas...",
  str_homestory_chat_33121008 = "Claro.",
  str_homestory_chat_33121009 = "Ah. PlayerName, você é um cara otimista!",
  str_homestory_chat_33121010 = "Hã? Meus sonhos te levaram a essa conclusão?",
  str_homestory_chat_33121011 = "Sim! Aqueles que vivem uma vida feliz e tratam os outros com otimismo...",
  str_homestory_chat_33121012 = "Eles terão muitas coisas bonitas com seus entes queridos em seus sonhos!",
  str_homestory_chat_33121013 = "Hehe. Há uma maneira ainda mais simples, porém.",
  str_homestory_chat_33121014 = "Venha me ver sempre que quiser ter um sonho doce!",
  str_homestory_chat_33121015 = "Pode deixar!",
  str_homestory_chat_33122001 = "Um mundo sem Eclipsitas.",
  str_homestory_chat_33122002 = "Uau. Por favor, dê-me um minuto para processar isso...",
  str_homestory_chat_33122003 = "Isso seria uma bolha sem qualquer mancha!",
  str_homestory_chat_33122004 = "A bolha mais linda e perfeita!",
  str_homestory_chat_33122005 = "O que você fez lá?",
  str_homestory_chat_33122006 = "Eu viajei por aí com todos.",
  str_homestory_chat_33122007 = "Uau. Eu gostaria de estar lá com você!",
  str_homestory_chat_33122008 = "Abraçamos o vento e assistimos ao nascimento de um novo mundo juntos no topo da Colossus...",
  str_homestory_chat_33122009 = "Trabalhamos juntos para restaurar nossa pátria.",
  str_homestory_chat_33122010 = "Que gentil e altruísta você é, até mesmo em seus sonhos!",
  str_homestory_chat_33122011 = "É muito importante restaurar as cores da bolha mesmo.",
  str_homestory_chat_33122012 = "Você me levaria com você na próxima vez para experimentarmos juntos esse belo sonho?",
  str_homestory_chat_33122013 = "Claro, eu só não sei quando seria...",
  str_homestory_chat_33123001 = "Longzhou.",
  str_homestory_chat_33123002 = "Longzhou. Eu li sobre isso em um livro de contos de fadas...",
  str_homestory_chat_33123003 = "Os contos de fadas de lá são bastante profundos.",
  str_homestory_chat_33123004 = "Eles gostam de usar palavras grandes e frases estranhas. Difícil para eu entender...",
  str_homestory_chat_33123005 = "A cultura de Longzhou é de fato profunda e extensa.",
  str_homestory_chat_33123006 = "Seus gadgets, calendário e Aurorianos são realmente intrigantes.",
  str_homestory_chat_33123007 = "Sério? Nunca vi um Aurorian de Longzhou.",
  str_homestory_chat_33123008 = "Vou pedir ao meu ancestral para me dar um vislumbre esta noite em meu sonho.",
  str_homestory_chat_33123009 = "Sério?",
  str_homestory_chat_33123010 = "Que tal se eu te apresentar a alguns dos Aurorians da próxima vez?",
  str_homestory_chat_33123011 = "Viva! Você é tão legal comigo, assim como meu ancestral!",
  str_homestory_chat_33124001 = "Um show de circo.",
  str_homestory_chat_33124002 = "Hmm... Um show?",
  str_homestory_chat_33124003 = "Eu assisti muitos quando estava no circo...",
  str_homestory_chat_33124004 = "Embora eu não me lembre muito...",
  str_homestory_chat_33124005 = "Eu sei com certeza que eles foram artistas incríveis!",
  str_homestory_chat_33124006 = "Qual é a sua parte favorita do show?",
  str_homestory_chat_33124007 = "Acho que o arremesso de facas?",
  str_homestory_chat_33124008 = "O arremesso de facas? Não sabia que você gostava da emoção.",
  str_homestory_chat_33124009 = "É emocionante e sempre acaba bem!",
  str_homestory_chat_33124010 = "É por isso que também sou fã.",
  str_homestory_chat_33124011 = "Acho que o show de mágica?",
  str_homestory_chat_33124012 = "O show de mágica? Jeno é um mágico fabuloso!",
  str_homestory_chat_33124013 = "Lembro-me de como era misterioso! Ele podia contar muito simplesmente desenhando algumas cartas!",
  str_homestory_chat_33124014 = "Hmm... Sinto falta de todos do circo...",
  str_homestory_chat_33124015 = "Vamos assistir a um espetáculo de circo juntos se tivermos a chance!",
  str_homestory_chat_33124016 = "Negócio!",
  str_homestory_chat_33125001 = "Eraveil.",
  str_homestory_chat_33125002 = "Eraveil... Essa é a sua cidade natal, não é?",
  str_homestory_chat_33125003 = "Eu nasci em um navio. Lar é um conceito estranho para mim.",
  str_homestory_chat_33125004 = "Você gosta de Eraveil?",
  str_homestory_chat_33125005 = "Sim, meu povo estava vivendo lá por gerações, afinal.",
  str_homestory_chat_33125006 = "Mas eu passei dezessete anos no subsolo.",
  str_homestory_chat_33125007 = "Ainda há muito que eu não sei sobre meus antepassados.",
  str_homestory_chat_33125008 = "Essa é uma das razões pela qual estou viajando.",
  str_homestory_chat_33125009 = "Uau. O Celestita também está tentando aprender sobre seus ancestrais?",
  str_homestory_chat_33125010 = "Somos bastante parecidos, não somos?",
  str_homestory_chat_33125011 = "Talvez meu ancestral conheça o seu?",
  str_homestory_chat_33125012 = "Talvez eles costumavam ser bons amigos!",
  str_homestory_chat_33125013 = "Haha. Isso é um pensamento muito interessante.",
  str_homestory_chat_33125014 = "Hehe. Nossos ancestrais devem estar muito felizes em nos ver continuar a amizade deles!",
  str_homestory_chat_33299999 = "Você tem algo que quer proteger?",
  str_homestory_chat_33221001 = "As coisas que eu quero proteger...",
  str_homestory_chat_33221002 = "Existem tantos, você sabe.",
  str_homestory_chat_33221003 = "Você pode ser mais específico?",
  str_homestory_chat_33221004 = "Hmm... É difícil descrever.",
  str_homestory_chat_33221005 = "Que tipo de coisas você está perguntando?",
  str_homestory_chat_33221006 = "De conceitos grandiosos como ideais e crenças.",
  str_homestory_chat_33221007 = "Até os pequenos e intrincados detalhes.",
  str_homestory_chat_33221008 = "Talvez você possa me dar alguns exemplos.",
  str_homestory_chat_33221009 = "E se forem...",
  str_homestory_chat_33221010 = "As facas que valorizo, meu corvo e seniores como Tweety.",
  str_homestory_chat_33221011 = "Nesse caso... Há algo que devo proteger agora mesmo!",
  str_homestory_chat_33221012 = "Para proteger o jantar de hoje à noite, devo impedir Vice de desenvolver um novo prato!!!",
  str_homestory_chat_33222001 = "O Colosso.",
  str_homestory_chat_33222002 = "Entendi.",
  str_homestory_chat_33222003 = "Seu companheiro deixou o campo de batalha para passar eras com você.",
  str_homestory_chat_33222004 = "E seus espíritos se entrelaçaram em uma harmonia milagrosa.",
  str_homestory_chat_33222005 = "Eu também fiquei chocado quando abri a herança de família... Eu entendo agora.",
  str_homestory_chat_33222006 = "Agora que você mencionou, parece que dividimos um destino parecido.",
  str_homestory_chat_33222007 = "De fato, até nossos ancestrais se encontraram há muito tempo atrás.",
  str_homestory_chat_33222008 = "Você me ajudou a cumprir minha missão, então agora, vou te ajudar a proteger a Colossus.",
  str_homestory_chat_33222009 = "Obrigado, com sua ajuda...",
  str_homestory_chat_33222010 = "Com certeza podemos fazer isso!",
  str_homestory_chat_33223001 = "A glória dos ancestrais.",
  str_homestory_chat_33223002 = "Eu entendo como ela se sente.",
  str_homestory_chat_33223003 = "Afinal, cheguei até aqui seguindo a vontade dos meus ancestrais.",
  str_homestory_chat_33223004 = "Não foi uma jornada fácil, cheia como estava de dúvidas...",
  str_homestory_chat_33223005 = "Mas eu cumpri meu destino. E você, para onde o seu caminho te levou?",
  str_homestory_chat_33223006 = "Há algumas conquistas...",
  str_homestory_chat_33223007 = "Parabéns para você então.",
  str_homestory_chat_33223008 = "Ainda estou trabalhando nisso...",
  str_homestory_chat_33223009 = "Então eu estarei cuidando de você.",
  str_homestory_chat_33223010 = "Se precisar de ajuda, sinta-se à vontade para me dizer.",
  str_homestory_chat_33223011 = "Não estou apenas agradecendo pela sua ajuda. Estou genuinamente fascinado pela história dos Celestitas.",
  str_homestory_chat_33223012 = "Obrigado.",
  str_homestory_chat_33224001 = "Justiça!",
  str_homestory_chat_33224002 = "Ah?",
  str_homestory_chat_33224003 = "Você também quer se tornar um camarada da justiça?",
  str_homestory_chat_33224004 = "Eu já sou!",
  str_homestory_chat_33224005 = "Cheguei a apreciar verdadeiramente o seu senso de justiça através do nosso tempo juntos.",
  str_homestory_chat_33224006 = "Acredito que você deve ser o candidato mais adequado.",
  str_homestory_chat_33224007 = "Claro que eu quero!",
  str_homestory_chat_33224008 = "Sério? Ter tanta determinação e crença é bastante impressionante.",
  str_homestory_chat_33224009 = "Mas este não é um trabalho fácil.",
  str_homestory_chat_33224010 = "Você gostaria de ser meu assistente?",
  str_homestory_chat_33224011 = "Nossas ações contra o mal à noite certamente serão mais eficazes com você por perto.",
  str_homestory_chat_33224012 = "Uh, se for sobre isso, por favor me permita pensar um pouco mais sobre isso!",
  str_homestory_chat_33225001 = "Amizade.",
  str_homestory_chat_33225002 = "A amizade é realmente linda.",
  str_homestory_chat_33225003 = "Eu estava sempre em movimento, mudando de empregos e nunca realmente me estabelecendo.",
  str_homestory_chat_33225004 = "Mas agora, encontrei algumas pessoas incríveis para chamar de amigos, como meu veterano na União Mensageira e aquele amigo especial à noite.",
  str_homestory_chat_33225005 = "Eles são os amigos que eu desejo proteger.",
  str_homestory_chat_33225006 = "Que tipo de amizade você quer proteger?",
  str_homestory_chat_33225007 = "A amizade com todos no Colossus!",
  str_homestory_chat_33225008 = "Certo, todos no Colossus são muito legais.",
  str_homestory_chat_33225009 = "É só que eu estou acostumado a uma vida de manter distância das pessoas.",
  str_homestory_chat_33225010 = "Parece que ainda não estou pronto para fazer amizade com todos.",
  str_homestory_chat_33225011 = "Então, se estamos falando sobre o presente...",
  str_homestory_chat_33225012 = "Minha amizade com você!",
  str_homestory_chat_33225013 = "Desculpe, eu apenas... Eu não acho que mencionei você.",
  str_homestory_chat_33225014 = "Afinal, você estar ao meu lado se tornou algo a que me acostumei.",
  str_homestory_chat_33225015 = "Permita-me corrigir.",
  str_homestory_chat_33225016 = "Proteger nossa amizade é extremamente importante.",
  str_homestory_chat_33225017 = "É minha honra! Vou valorizar esta amizade!",
  str_homestory_chat_33399999 = "Se um dia você acordar e for a única pessoa restante no mundo, o que você faria?",
  str_homestory_chat_33321001 = "Continue a dormir.",
  str_homestory_chat_33321002 = "Devo estar sonhando.",
  str_homestory_chat_33321003 = "Por que é assim? Normalmente, as pessoas iriam imediatamente explorar e fazer coisas que normalmente não podem fazer, certo?",
  str_homestory_chat_33321004 = "Mas eu sou a estrela!",
  str_homestory_chat_33321005 = "Normalmente, muitas coisas incomuns acontecem.",
  str_homestory_chat_33321006 = "Hahaha, você, de todas as pessoas, é ainda mais arrogante do que eu.",
  str_homestory_chat_33321007 = "Você já pensou nisso? Se todos desaparecessem, suas habilidades psíquicas seriam inúteis, certo?",
  str_homestory_chat_33321008 = "Bem... Já que não há nada para fazer, eu realmente deveria apenas ir dormir.",
  str_homestory_chat_33321009 = "O que é que você quer fazer, mas não pode?",
  str_homestory_chat_33321010 = "Humph. A princípio, parece que há muito, mas ao pensar melhor, não parece haver muito.",
  str_homestory_chat_33321011 = "Farei o que quiser fazer, as regras não podem me parar.",
  str_homestory_chat_33321012 = "Não existe tal coisa como \"algo que você normalmente não pode fazer\"!",
  str_homestory_chat_33321013 = "Que cara perigoso...",
  str_homestory_chat_33322001 = "Primeiro, corra para o parque de diversões em Umbraton ou Harbour City.",
  str_homestory_chat_33322002 = "Então, vamos aproveitar as atividades que geralmente exigem entrar na fila!",
  str_homestory_chat_33322003 = "Devo te chamar... de honesto, ou tenso?",
  str_homestory_chat_33322004 = "Seu sonho pode se realizar apenas se infiltrando no parque de diversões à meia-noite.",
  str_homestory_chat_33322005 = "... Quem pensaria em fazer uma coisa dessas!?",
  str_homestory_chat_33322006 = "Você é a radiante e irrestrita Senhora Pepita.",
  str_homestory_chat_33322007 = "Vamos, eu te levo lá esta noite.",
  str_homestory_chat_33322008 = "(Oh, não. Estou realmente um pouco encantado...)",
  str_homestory_chat_33323001 = "Vá à livraria para ler livros gratuitos",
  str_homestory_chat_33323002 = "Posso assistir o dia todo, sentar onde eu quiser, e não me preocupar com o balconista me encarando... Ah, céu!",
  str_homestory_chat_33323003 = "...",
  str_homestory_chat_33323004 = "Sei que meu desejo é humilde, mas você não precisa me olhar tão sem palavras...",
  str_homestory_chat_33323005 = "Você entendeu errado, eu não achei que seu desejo fosse humilde de forma alguma.",
  str_homestory_chat_33323006 = "Mas se você quiser ler livros de graça, tudo o que precisa fazer é vestir uma roupa elegante... e você pode entrar na livraria e escolher o que quiser.",
  str_homestory_chat_33323007 = "Uma vez que você selecionou, basta mencionar o nome de qualquer nobre. A livraria pode coletar o pagamento no final do Tsuki.",
  str_homestory_chat_33323008 = "Esses nobres tratam suas contas mensais como flocos de neve, nunca se preocupam em verificar uma por uma.",
  str_homestory_chat_33323009 = "V-Você... Is-Isso é um crime, não é?",
  str_homestory_chat_33323010 = "Ha! Esses nobres ignorantes, sou eu quem está espalhando conhecimento para o povo comum... E você chama isso de crime?",
  str_homestory_chat_33323011 = "Eu diria que é minha bênção.",
  str_homestory_chat_33323012 = "...",
  str_homestory_chat_33324001 = "Tomando banho no rio",
  str_homestory_chat_33324002 = "Pfft!",
  str_homestory_chat_33324003 = "*Tosse*... Para ser honesto com você, eu queria fazer isso há muito tempo.",
  str_homestory_chat_33324004 = "Mas você ainda está preocupado... certo?",
  str_homestory_chat_33324005 = "Não, eu vou o tempo todo.",
  str_homestory_chat_33324006 = "O quê?! Você não está preocupado—",
  str_homestory_chat_33324007 = "Alguém está vindo?",
  str_homestory_chat_33324008 = "Petey está aqui. Além disso, que tipo de pessoa ficaria olhando para os outros enquanto eles estão tomando banho?",
  str_homestory_chat_33324009 = "Além disso, todos são iguais, do que há para se envergonhar?",
  str_homestory_chat_33324010 = "... Não, não, espere! Nem pense em me enganar para tomar banho no rio agora mesmo!",
  str_homestory_chat_33324011 = "Atacado por piranhas?",
  str_homestory_chat_33324012 = "Quando vou tomar banho no rio, geralmente estou coberto de lama.",
  str_homestory_chat_33324013 = "Os tubarões seriam envenenados e desmaiariam.",
  str_homestory_chat_33324014 = "Tão grandioso... não, não foi isso que eu quis olhar!",
  str_homestory_chat_33325001 = "Sentado no trono de Lumópolis",
  str_homestory_chat_33325002 = "Você ainda vai cruzar as pernas!",
  str_homestory_chat_33325003 = "Suspiro, estou sem ideias, estou sentado há um tempo agora.",
  str_homestory_chat_33325004 = "O quê?! Deixe-me perguntar primeiro, você não está autorizado, certo...?",
  str_homestory_chat_33325005 = "Será que o pai de Carleen também vai me convidar graciosamente?",
  str_homestory_chat_33325006 = "A cadeira é confortável para se sentar?",
  str_homestory_chat_33325007 = "Tsc, nada confortável, é tão difícil!",
  str_homestory_chat_33325008 = "Pelo bem de Carleen, deixei uma almofada lá.",
  str_homestory_chat_33325009 = "Realmente espero que o Senhor da Cidade me agradeça... Hahaha!",
  str_homestory_chat_33325010 = "Como você chegou lá?",
  str_homestory_chat_33325011 = "Naquela noite, eu estava grafitando em uma bela parede branca, então os guardas chegaram...",
  str_homestory_chat_33325012 = "Acabei de descobrir que é o Tribunal de Justiça de Lumopolis.",
  str_homestory_chat_33325013 = "...",
  str_homestory_chat_33325014 = "E então eu corri para o lugar onde está o trono do Senhor da Cidade!",
  str_homestory_chat_33325015 = "Pela segurança, tenho que manter uma certa distância de você...",
  str_homestory_chat_33429999 = "Você se importaria em compartilhar algumas coisas interessantes sobre este momento?",
  str_homestory_chat_33421001 = "Claro, mas você não precisa ser tão educado.",
  str_homestory_chat_33421002 = "Faz tanto tempo. Eu só sei muito pouco sobre o mundo agora.",
  str_homestory_chat_33421003 = "E eu poderia me tornar mais um fardo do que uma ajuda se não me adaptar ao mundo moderno.",
  str_homestory_chat_33421004 = "Por favor, me conte mais sobre o mundo.",
  str_homestory_chat_33421005 = "Ah, não se preocupe com isso. Você vê, passei os últimos dezessete anos no subsolo.",
  str_homestory_chat_33421006 = "Ainda estou muito no processo de explorar este mundo!",
  str_homestory_chat_33421007 = "Então, podemos compartilhar nossas experiências uns com os outros.",
  str_homestory_chat_33421008 = "Vamos aproveitar o mundo juntos!",
  str_homestory_chat_33421009 = "É realmente um grande mundo.",
  str_homestory_chat_33421010 = "É um prazer compartilhar meus pensamentos com você.",
  str_homestory_chat_33421011 = "Em nome de Aquiles, também compartilharei com você tudo o que sei.",
  str_homestory_chat_33421012 = "Se deseja saber sobre seus companheiros celestitas, estou feliz em compartilhar suas histórias com você.",
  str_homestory_chat_33421013 = "Estou muito interessado! Fale-me sobre eles algum dia.",
